1	/**
2	 * §10 — cache-aware prompt assembly (D5).
3	 *
4	 * The layout is fixed and the content migrates through it:
5	 *
6	 *   Zone A  system contract + MCP tool schemas      frozen, cached permanently
7	 *   Zone B  task root summary, then branch summaries in CREATION ORDER
8	 *   Zone C  the ACTIVE branch expanded in full + this turn's tool results
9	 *   tail    `context_fetch`/`context_search`/`context_peek` output (D6)
10	 *
11	 * The single idea the whole file exists to protect: provider caches are keyed on
12	 * a *prefix*, so an edit in the middle invalidates everything after it. Zone B is
13	 * therefore never relevance-ordered (§10 rule 1) — relevance is expressed by
14	 * expansion in Zone C, and new summaries land at the END of Zone B where they
15	 * invalidate only the suffix that Zone C rewrites anyway (rule 2). Retrieval
16	 * results go after Zone C (rule 3) for the same reason.
17	 *
18	 * Block ids are stable functions of content coordinates (node id + summary
19	 * version, or L0 seq), because §17's cache-assertion harness proves "which
20	 * prefix ranges survived this event" by comparing ids and token counts across
21	 * two assemblies. If an id moved for a reason unrelated to content, that harness
22	 * silently stops testing anything.
23	 */
24	import { createHash } from 'node:crypto';
25	import { replyHeadroom } from './budgets.js';
26	import { DEFAULT_CONFIG } from '../config.js';
27	import { StoreInvariantError } from '../contracts/index.js';
28	import type {
29	  AssembleOptions,
30	  AssembledPrompt,
31	  BlobStore,
32	  BudgetReport,
33	  ChatMessage,
34	  CompletionRequest,
35	  DeliveredBlock,
36	  DeliveryPrompt,
37	  DeliveryReceipt,
38	  NodeId,
39	  PromptAssembler,
40	  PromptBlock,
41	  TailEntry,
42	  Tokenizer,
43	  ToolSchema,
44	  TraceLog,
45	  TreeNode,
46	  TreeStore,
47	  Zone,
48	} from '../contracts/index.js';
49	import {
50	  renderActiveHeader,
51	  renderActiveMap,
52	  renderEvent,
53	  renderLinksBlock,
54	  renderSummaryBlock,
55	  renderTailBlock,
56	  truncateToTokens,
57	} from './format.js';
58	
59	export interface ZoneAssemblerDeps {
60	  store: TreeStore;
61	  blobs: BlobStore;
62	  /**
63	   * L0 is required, not optional: Zone C is "the active branch's raw detail",
64	   * and L1 stores only the seq coordinates of that detail (§6).
65	   */
66	  trace: TraceLog;
67	  tokenizer: Tokenizer;
68	  /**
69	   * Zone A's frozen text. Byte-identical across every turn of a session — any
70	   * per-turn value leaking in here (a timestamp, a node count, a budget number)
71	   * permanently defeats caching for the whole session.
72	   */
73	  systemContract: string;
74	  budgets?: { zoneB: number; zoneC: number };
75	  /**
76	   * The host's context window in tokens. Host-supplied on purpose: it is a
77	   * property of the deployment, not something this library can derive or
78	   * sensibly default. Supplying it is what makes `BudgetReport.window`,
79	   * `windowRemaining` and `overWindow` meaningful, and it is the input
80	   * `deriveZoneBudgets` needs so the zone allowances come from ONE measured
81	   * number instead of two independently chosen constants.
82	   */
83	  window?: number;
84	  /**
85	   * D5 experiment 4: mark a THIRD
86	   * provider breakpoint at the end of Zone C's stable run — every block except
87	   * the descendant map (`C:map:*`), which churns on every edit and must ride
88	   * after the marker (see the comment above `zoneC`). Anthropic honours up to
89	   * 4; the shipped default emits 2 (Zone A/B, Zone B/C) and leaves Zone C fresh
90	   * on every turn. Defaults to `false` — today's behaviour — because turning
91	   * this on is a request-shape change (`toMessages` splits Zone C into two
92	   * messages instead of one) that a caller opts into deliberately, not a bug
93	   * fix applied silently underneath existing callers.
94	   */
95	  cacheZoneCBreakpoint?: boolean;
96	  /**
97	   * Tokens reserved for the reply when enforcing the window. Defaults to
98	   * `replyHeadroom({ window })` — the window fraction — so a host that knows its
99	   * model's maximum output should pass the measured figure instead.
100	   */
101	  replyReserve?: number;
102	}
103	
104	/** A Zone B node contributes a summary block plus an optional links block; the
105	 *  pair is kept or dropped as a unit so a dropped summary never leaves orphan
106	 *  link annotations pointing at prose the model cannot see. */
107	interface ZoneBEntry {
108	  nodeId: NodeId;
109	  isRoot: boolean;
110	  blocks: PromptBlock[];
111	  tokens: number;
112	}
113	
114	export interface ZoneBSelection {
115	  /**
116	   * Branch ids to keep in Zone B, chosen by the caller (e.g. a DSA-style
117	   * top-k selector in the eval harness). `undefined` keeps every branch —
118	   * so k >= branch count and no selection at all are the same code path and
119	   * neither perturbs the prefix. The task root and the active branch are not
120	   * selectable: the root is the anchor and the active branch never appears in
121	   * Zone B anyway. Selected branches keep creation order (rule 1) — selection
122	   * changes membership, never position.
123	   */
124	  keepBranches?: ReadonlySet<NodeId>;
125	}
126	
127	export class ZoneAssembler implements PromptAssembler {
128	  private readonly deps: ZoneAssemblerDeps;
129	  private readonly budgets: { zoneB: number; zoneC: number };
130	  /** D6 soft offloading: acknowledged fetched detail can leave at a phase boundary. */
131	  private tail: TailEntry[] = [];
132	  /** Delivery is explicit and keyed by both coordinate and selected bytes. */
133	  private readonly deliveredTail = new Set<string>();
134	
135	  constructor(deps: ZoneAssemblerDeps) {
136	    this.deps = deps;
137	    this.budgets = deps.budgets ?? { ...DEFAULT_CONFIG.budgets };
138	  }
139	
140	  /** Appends one retrieval result to the tail (after Zone C — rule 3). */
141	  appendTail(entry: TailEntry): void {
142	    this.tail.push({ ...entry });
143	  }
144	
145	  tailEntries(): readonly TailEntry[] {
146	    return this.tail.map((entry) => ({ ...entry }));
147	  }
148	
149	  /**
150	   * Commit a successfully delivered candidate. Replaying an acknowledgement is
151	   * harmless, and an old receipt cannot acknowledge or evict replacement text
152	   * under the same ID. This changes only the ephemeral assembly buffer.
153	   */
154	  acknowledgeDelivery(receipt: DeliveryReceipt): void {
155	    if (receipt.version !== 1) throw new RangeError('unsupported delivery receipt version');
156	    for (const block of receipt.blocks) {
157	      if (block.id.startsWith('tail:')) this.deliveredTail.add(deliveryKey(block));
158	    }
159	    if (receipt.tailSource === 'internal') {
160	      const evicted = new Set(receipt.evictedTail.map(deliveryKey));
161	      this.tail = this.tail.filter((entry) => !evicted.has(deliveryKey(tailIdentity(entry))));
162	    }
163	  }
164	
165	  /**
166	   * D6: delivered fetched payloads die at phase boundaries. Unacknowledged
167	   * selected payloads survive. This does not touch L1, does not
168	   * close or open a node, and does not re-summarize. Phase state belongs to the
169	   * segmenter; the assembler only reads it.
170	   */
171	  onPhaseTransition(): void {
172	    this.tail = this.tail.filter((entry) => !entry.ephemeral || !this.deliveredTail.has(deliveryKey(tailIdentity(entry))));
173	  }
174	
175	  assemble(options: AssembleOptions = {}): DeliveryPrompt {
176	    const { store } = this.deps;
177	    const root = store.root();
178	
179	    const activeNodeId = options.activeNodeId ?? store.openPhase()?.id ?? null;
180	    const active = activeNodeId === null ? null : store.getNode(activeNodeId);
181	    if (activeNodeId !== null && active === null) {
182	      throw new StoreInvariantError(`assemble: unknown activeNodeId ${activeNodeId}`);
183	    }
184	
185	    const zoneA = this.zoneA(options.toolSchemasText);
186	
187	    const zoneBBudget = options.zoneBBudget ?? this.budgets.zoneB;
188	    const zoneB = this.zoneB(root, this.activeBranchId(active, root), zoneBBudget, options.selection);
189	
190	    const zoneCBudget = options.zoneCBudget ?? this.budgets.zoneC;
191	    const zoneC = this.zoneC(active, zoneCBudget);
192	
193	    const tailEntries = [...(options.tail ?? this.tail)];
194	    const tailBlocks = tailEntries.map((entry) =>
195	      this.block('tail', `tail:${entry.id}`, renderTailBlock(entry.id, entry.text, entry.ephemeral)),
196	    );
197	
198	    // Rule 5: breakpoints at the Zone A/B and Zone B/C boundaries, nowhere else.
199	    const cacheBreakpoints: string[] = [];
200	    for (const zoneBlocks of [zoneA, zoneB.blocks]) {
201	      const last = zoneBlocks.at(-1);
202	      if (last === undefined) continue;
203	      last.cacheBreakpointAfter = true;
204	      cacheBreakpoints.push(last.id);
205	    }
206	    // Experiment 4's 3rd breakpoint, opt-in only (`cacheZoneCBreakpoint`): the
207	    // last Zone C block that is not the descendant map, so the map (and any
208	    // tail) keep riding uncached after it exactly as `renderActiveMap`'s
209	    // comment above `zoneC` requires.
210	    if (this.deps.cacheZoneCBreakpoint === true) {
211	      const lastStable = [...zoneC.blocks].reverse().find((b) => !b.id.startsWith('C:map:'));
212	      if (lastStable !== undefined) {
213	        lastStable.cacheBreakpointAfter = true;
214	        cacheBreakpoints.push(lastStable.id);
215	      }
216	    }
217	
218	    const overBudget: Zone[] = [];
219	    // The asymmetry is deliberate: Zone B reports its degradation through
220	    // `droppedFromZoneB`, so `overBudget` only names it when dropping was not
221	    // enough. Zone C has no dropped-list field, so truncation is reported here —
222	    // a silent drop or truncation is indistinguishable from a summarizer bug.
223	    if (zoneB.tokens > zoneBBudget) overBudget.push('B');
224	    if (zoneC.truncated) overBudget.push('C');
225	
226	    const window = options.window ?? this.deps.window ?? null;
227	    if (window !== null && (!Number.isFinite(window) || window <= 0)) {
228	      throw new RangeError('window must be a finite positive number of tokens');
229	    }
230	    // Window enforcement proposes a candidate without committing buffer state.
231	    // Selected tail payloads stay until their exact bytes are acknowledged;
232	    // already-delivered ephemeral payloads leave first, then Zone C events
233	    // oldest-first under its existing selection policy. Both are reported.
234	    // The tail rides after the last breakpoint, so evicting it re-bills nothing.
235	    const evictedFromTail: string[] = [];
236	    const evictedTail: DeliveredBlock[] = [];
237	    let droppedFromZoneC = 0;
238	    if (window !== null) {
239	      const reply = this.deps.replyReserve ?? replyHeadroom({ window }).tokens;
240	      if (!Number.isFinite(reply) || reply < 0) throw new RangeError('replyReserve must be finite and nonnegative');
241	      const over = (): number =>
242	        sumTokens(zoneA) + zoneB.tokens + sumTokens(zoneC.blocks) + sumTokens(tailBlocks) + reply - window;
243	      let i = 0;
244	      while (over() > 0 && i < tailEntries.length) {
245	        const entry = tailEntries[i]!;
246	        const identity = tailIdentity(entry);
247	        if (entry.ephemeral && this.deliveredTail.has(deliveryKey(identity))) {
248	          evictedFromTail.push(entry.id);
249	          evictedTail.push(identity);
250	          tailEntries.splice(i, 1);
251	          tailBlocks.splice(i, 1);
252	        } else {
253	          i += 1;
254	        }
255	      }
256	      while (over() > 0) {
257	        const idx = zoneC.blocks.findIndex((b) => b.id.startsWith('C:event:'));
258	        if (idx < 0) break;
259	        zoneC.blocks.splice(idx, 1);
260	        droppedFromZoneC += 1;
261	      }
262	    }
263	
264	    const tailTokens = sumTokens(tailBlocks);
265	    const budgets: BudgetReport = {
266	      zoneA: sumTokens(zoneA),
267	      zoneB: zoneB.tokens,
268	      zoneC: sumTokens(zoneC.blocks),
269	      tail: tailTokens,
270	      total: 0,
271	      overBudget,
272	      droppedFromZoneB: zoneB.dropped,
273	      window,
274	      windowRemaining: null,
275	      overWindow: false,
276	      replyAllowance: null,
277	      evictedFromTail,
278	      droppedFromZoneC,
279	    };
280	    budgets.total = budgets.zoneA + budgets.zoneB + budgets.zoneC + budgets.tail;
281	    // The one constraint that is not a matter of allocation: this prompt either
282	    // fits the host's window or cannot be sent. Report any residual overflow
283	    // after selection instead of cutting an unacknowledged selected payload.
284	    // The host must also count its serialized request framing and native tools
285	    // before sending: these block counts are in the supplied tokenizer's units.
286	    if (window !== null) {
287	      budgets.windowRemaining = window - budgets.total;
288	      budgets.overWindow = budgets.total > window;
289	      // The largest reply that fits beside what was just built. A caller passes
290	      // this straight to the provider as `max_tokens`, which is the honest form
291	      // of a reply limit: arithmetic per turn rather than a number anyone
292	      // picked. It shrinks as the session grows, so a small-window model keeps
293	      // iterating on short answers instead of the request becoming invalid.
294	      budgets.replyAllowance = Math.max(0, window - budgets.total);
295	    }
296	
297	    const blocks = [...zoneA, ...zoneB.blocks, ...zoneC.blocks, ...tailBlocks];
298	    const deliveryReceipt: DeliveryReceipt = Object.freeze({
299	      version: 1,
300	      blocks: Object.freeze(blocks.map(blockIdentity)),
301	      tailSource: options.tail === undefined ? 'internal' : 'supplied',
302	      evictedTail: Object.freeze(evictedTail),
303	    });
304	    return {
305	      system: zoneA.map((b) => b.text).join('\n\n'),
306	      blocks,
307	      budgets,
308	      cacheBreakpoints,
309	      deliveryReceipt,
310	    };
311	  }
312	
313	  // ── zones ──────────────────────────────────────────────────────────────────
314	
315	  private zoneA(toolSchemasText: string | undefined): PromptBlock[] {
316	    const blocks = [this.block('A', 'A:system', this.deps.systemContract)];
317	    if (toolSchemasText !== undefined && toolSchemasText !== '') {
318	      blocks.push(this.block('A', 'A:tools', toolSchemasText));
319	    }
320	    return blocks;
321	  }
322	
323	  /**
324	   * Zone B in creation order (rule 1) from `nodesInCreationOrder()`, restricted
325	   * to the task root and its direct branches — deeper nodes are detail, reachable
326	   * by expansion in Zone C or by `context_fetch`, and putting them here would
327	   * spend the 8k budget on exactly the content Zone C already carries.
328	   */
329	  private zoneB(
330	    root: TreeNode | null,
331	    activeBranchId: NodeId | null,
332	    budget: number,
333	    selection?: ZoneBSelection,
334	  ): { blocks: PromptBlock[]; tokens: number; dropped: NodeId[] } {
335	    if (root === null) return { blocks: [], tokens: 0, dropped: [] };
336	    const { store } = this.deps;
337	    const entries: ZoneBEntry[] = [];
338	
339	    for (const node of store.nodesInCreationOrder()) {
340	      const isRoot = node.id === root.id;
341	      if (!isRoot && node.parent_id !== root.id) continue;
342	      // The active branch's detail is in Zone C; its summary would duplicate it.
343	      // Every other block keeps its position, so promoting or demoting a branch
344	      // never reorders its neighbours.
345	      if (!isRoot && node.id === activeBranchId) continue;
346	      // Caller-side top-k selection (ZoneBSelection): a branch outside the
347	      // keep-set is excluded before budget accounting — selection is a
348	      // relevance decision, rule-4 budget dropping remains the overflow valve.
349	      if (!isRoot && selection?.keepBranches !== undefined && !selection.keepBranches.has(node.id)) continue;
350	
351	      const summary = store.currentSummary(node.id);
352	      if (summary === null) continue;
353	
354	      const blocks = [
355	        this.block(
356	          'B',
357	          `${isRoot ? 'B:root' : 'B:summary'}:${node.id}:${summary.version}`,
358	          renderSummaryBlock(node, summary, isRoot),
359	          node.id,
360	        ),
361	      ];
362	      const links = store.linksFrom(node.id);
363	      if (links.length > 0) {
364	        blocks.push(
365	          this.block('B', `B:links:${node.id}:${links.length}`, renderLinksBlock(node, links), node.id),
366	        );
367	      }
368	      entries.push({ nodeId: node.id, isRoot, blocks, tokens: sumTokens(blocks) });
369	    }
370	
371	    // Rule 4 degradation: drop the OLDEST summaries first, never reorder. The
372	    // root summary is exempt — it is the task anchor a resumed session reads
373	    // first, and it is also the oldest, so oldest-first would drop it first.
374	    const dropped: NodeId[] = [];
375	    let tokens = entries.reduce((sum, entry) => sum + entry.tokens, 0);
376	    for (const entry of entries) {
377	      if (tokens <= budget) break;
378	      if (entry.isRoot) continue;
379	      dropped.push(entry.nodeId);
380	      tokens -= entry.tokens;
381	    }
382	
383	    const droppedIds = new Set(dropped);
384	    const blocks = entries.filter((e) => !droppedIds.has(e.nodeId)).flatMap((e) => e.blocks);
385	    return { blocks, tokens, dropped };
386	  }
387	
388	  /**
389	   * Zone C: the active branch expanded in full, read straight out of L0 over the
390	   * node's seq span, plus this turn's tool results — for an OPEN branch the read
391	   * runs to `lastSeq()` so results appended since the last ingest pass are
392	   * present (§10 rule 2: "+ this turn's tool results").
393	   */
394	  private zoneC(
395	    active: TreeNode | null,
396	    budget: number,
397	  ): { blocks: PromptBlock[]; truncated: boolean } {
398	    if (active === null) return { blocks: [], truncated: false };
399	    const { store, blobs, trace } = this.deps;
400	
401	    const blocks = [this.block('C', `C:head:${active.id}`, renderActiveHeader(active), active.id)];
402	
403	    if (active.span_start_seq !== null) {
404	      const from = active.span_start_seq;
405	      const recorded = active.span_end_seq ?? from;
406	      const to = active.status === 'open' ? Math.max(recorded, trace.lastSeq()) : recorded;
407	      for (const event of trace.read({ from, to })) {
408	        blocks.push(this.block('C', `C:event:${event.seq}`, renderEvent(event, blobs)));
409	      }
410	    }
411	
412	    // The descendant map goes LAST: it grows with every edit, and churn ahead
413	    // of the append-only event stream voids the events' cache (see
414	    // renderActiveMap). Callers that cache Zone C must keep it after their
415	    // moving breakpoint.
416	    const descendants = store.descendants(active.id);
417	    if (descendants.length > 0) {
418	      blocks.push(this.block('C', `C:map:${active.id}`, renderActiveMap(descendants), active.id));
419	    }
420	
421	    return { blocks, truncated: this.fitZoneC(blocks, budget) };
422	  }
423	
424	  /**
425	   * Rule 4: when Zone C is over budget, truncate the LARGEST detail blocks. Cap
426	   * chosen by water-filling (smallest cap `c` where `sum(min(tokens, c))` fits),
427	   * so the cost falls on the blocks actually responsible for the overflow and
428	   * small blocks survive intact. Returns whether anything was truncated.
429	   */
430	  private fitZoneC(blocks: PromptBlock[], budget: number): boolean {
431	    const total = sumTokens(blocks);
432	    if (total <= budget) return false;
433	
434	    const fill = (cap: number): number =>
435	      blocks.reduce((sum, block) => sum + Math.min(block.tokens, cap), 0);
436	    let lo = 0;
437	    // reduce, not Math.max(...spread): Zone C can hold one block per L0 event.
438	    let hi = blocks.reduce((max, block) => Math.max(max, block.tokens), 0);
439	    while (lo < hi) {
440	      const mid = Math.floor((lo + hi) / 2);
441	      if (fill(mid) <= budget) lo = mid + 1;
442	      else hi = mid;
443	    }
444	    // `lo` is now the smallest cap that does NOT fit; the largest that fits is
445	    // lo - 1 (fill(0) === 0 always fits, so lo >= 1).
446	    const cap = lo - 1;
447	
448	    for (const block of blocks) {
449	      if (block.tokens <= cap) continue;
450	      block.text = truncateToTokens(block.text, cap, this.deps.tokenizer);
451	      block.tokens = this.deps.tokenizer.count(block.text);
452	    }
453	    return true;
454	  }
455	
456	  // ── helpers ────────────────────────────────────────────────────────────────
457	
458	  /**
459	   * The direct branch of the task root that owns `active`. Zone C may be pointed
460	   * at a file node deep inside a phase; the summary that would duplicate it is
461	   * still the phase's. When `active` IS the root, nothing is excluded — Zone C
462	   * expands everything and the root summary stays as the anchor.
463	   */
464	  private activeBranchId(active: TreeNode | null, root: TreeNode | null): NodeId | null {
465	    if (active === null || root === null || active.id === root.id) return null;
466	    const path = this.deps.store.ancestorPath(active.id);
467	    return path[1]?.id ?? null;
468	  }
469	
470	  private block(zone: Zone, id: string, text: string, nodeId?: NodeId): PromptBlock {
471	    const block: PromptBlock = { zone, id, text, tokens: this.deps.tokenizer.count(text) };
472	    if (nodeId !== undefined) block.nodeId = nodeId;
473	    return block;
474	  }
475	}
476	
477	function blockIdentity(block: Pick<PromptBlock, 'id' | 'text'>): DeliveredBlock {
478	  return Object.freeze({ id: block.id, contentHash: createHash('sha256').update(block.text, 'utf8').digest('hex') });
479	}
480	
481	function tailIdentity(entry: TailEntry): DeliveredBlock {
482	  return blockIdentity({ id: `tail:${entry.id}`, text: renderTailBlock(entry.id, entry.text, entry.ephemeral) });
483	}
484	
485	function deliveryKey(block: DeliveredBlock): string {
486	  return JSON.stringify([block.id, block.contentHash]);
487	}
488	
489	function sumTokens(blocks: readonly PromptBlock[]): number {
490	  return blocks.reduce((sum, block) => sum + block.tokens, 0);
491	}
492	
493	/**
494	 * Does `zone` end at a §10 rule 5 breakpoint? Both provider-facing projections
495	 * below read this one predicate, so the system flag and the message flags cannot
496	 * drift apart — which is exactly how the Zone A marker got lost before.
497	 */
498	function zoneEndsAtBreakpoint(prompt: AssembledPrompt, zone: Zone): boolean {
499	  const last = prompt.blocks.filter((block) => block.zone === zone).at(-1);
500	  if (last === undefined) return false;
501	  return last.cacheBreakpointAfter === true || prompt.cacheBreakpoints.includes(last.id);
502	}
503	
504	function isMarked(prompt: AssembledPrompt, block: PromptBlock): boolean {
505	  return block.cacheBreakpointAfter === true || prompt.cacheBreakpoints.includes(block.id);
506	}
507	
508	/**
509	 * Splits one zone's blocks at its LAST marked block, so a breakpoint planted
510	 * anywhere inside a zone (not only at the zone's own end) still lands on a
511	 * message boundary a provider can key on. Two zone-B blocks are 1:1 with
512	 * `zoneEndsAtBreakpoint`'s old behaviour when the mark sits on the zone's final
513	 * block — `rest` is then empty and the caller emits one message, unchanged.
514	 * Zone C's experiment-4 mark (last block before `C:map:*`) is what this exists
515	 * for: everything through that block is one cacheable message, and the map
516	 * (plus anything after it in the zone) rides in a second, uncached message.
517	 */
518	function splitAtLastMark(
519	  prompt: AssembledPrompt,
520	  blocks: readonly PromptBlock[],
521	): { cached: readonly PromptBlock[]; rest: readonly PromptBlock[] } {
522	  let cut = -1;
523	  for (let i = 0; i < blocks.length; i += 1) {
524	    if (isMarked(prompt, blocks[i]!)) cut = i;
525	  }
526	  if (cut === -1) return { cached: [], rest: blocks };
527	  return { cached: blocks.slice(0, cut + 1), rest: blocks.slice(cut + 1) };
528	}
529	
530	/**
531	 * Provider-facing projection of an assembled prompt: one message per zone by
532	 * default, or two for a zone carrying an internal breakpoint (experiment 4's
533	 * opt-in 3rd marker) — the cached run up to and including the marked block,
534	 * then the remainder, uncached, so the models layer only has to translate a
535	 * flag into a provider-native one.
536	 *
537	 * Zone A is deliberately absent — it ships as `AssembledPrompt.system`, and
538	 * repeating it here would duplicate the frozen prefix. Its A/B breakpoint is the
539	 * system/messages boundary, which no message can express: that half of rule 5
540	 * travels as `CompletionRequest.systemCacheBreakpoint`, so build the request
541	 * with `toCompletionRequest` rather than assembling one around `toMessages`.
542	 */
543	export function toMessages(prompt: AssembledPrompt): ChatMessage[] {
544	  const messages: ChatMessage[] = [];
545	  for (const zone of ['B', 'C', 'tail'] as const) {
546	    const blocks = prompt.blocks.filter((block) => block.zone === zone);
547	    if (blocks.length === 0) continue;
548	    const { cached, rest } = splitAtLastMark(prompt, blocks);
549	    if (cached.length > 0) {
550	      messages.push({
551	        role: 'user',
552	        content: cached.map((block) => block.text).join('\n\n'),
553	        cacheBreakpoint: true,
554	      });
555	    }
556	    if (rest.length > 0) {
557	      messages.push({ role: 'user', content: rest.map((block) => block.text).join('\n\n') });
558	    }
559	  }
560	  return messages;
561	}
562	
563	/** Per-call knobs that are not the assembler's business (§11). */
564	export interface CompletionRequestOptions {
565	  maxTokens?: number;
566	  temperature?: number;
567	  /** Zone A's schemas as the provider's native tool list, not as prompt text. */
568	  tools?: readonly ToolSchema[];
569	  json?: boolean;
570	}
571	
572	/**
573	 * The whole prompt as one provider request — Zone A as `system`, zones B/C/tail
574	 * as messages, and BOTH rule 5 breakpoints attached.
575	 *
576	 * This exists because the two halves of rule 5 leave the assembler by different
577	 * doors: the B/C marker rides a message, while the A/B marker is the
578	 * system/messages boundary itself and needs a request-level flag. A caller that
579	 * built a request from `toMessages` alone dropped the Zone A marker silently —
580	 * nothing fails, the session just pays full price for the frozen prefix on every
581	 * turn (§17: this failure surfaces here and essentially nowhere else). Emitting
582	 * both from one function is what keeps them from drifting again.
583	 */
584	export function toCompletionRequest(
585	  prompt: AssembledPrompt,
586	  model: string,
587	  options: CompletionRequestOptions = {},
588	): CompletionRequest {
589	  const request: CompletionRequest = {
590	    model,
591	    system: prompt.system,
592	    messages: toMessages(prompt),
593	  };
594	  // An empty Zone A is not worth a cache write, and a marker on an empty text
595	  // block is a request the providers reject.
596	  if (prompt.system !== '' && zoneEndsAtBreakpoint(prompt, 'A')) {
597	    request.systemCacheBreakpoint = true;
598	  }
599	  if (options.maxTokens !== undefined) request.maxTokens = options.maxTokens;
600	  if (options.temperature !== undefined) request.temperature = options.temperature;
601	  if (options.tools !== undefined) request.tools = options.tools;
602	  if (options.json !== undefined) request.json = options.json;
603	  return request;
604	}
