1	/**
2	 * §10 prompt assembly — layered lifecycle layout (D5). The layout is fixed;
3	 * content migrates through it by lifecycle. Zone B is never relevance-ordered:
4	 * reordering the cached prefix is the cache killer.
5	 */
6	import type { NodeId } from './ids.js';
7	
8	export type Zone = 'A' | 'B' | 'C' | 'tail';
9	
10	export const ZONES: readonly Zone[] = ['A', 'B', 'C', 'tail'] as const;
11	
12	export interface PromptBlock {
13	  zone: Zone;
14	  /** Stable within a zone across turns — cache assertions key on this. */
15	  id: string;
16	  text: string;
17	  tokens: number;
18	  nodeId?: NodeId;
19	  /** Provider cache breakpoint emitted after this block (§10 rule 5). */
20	  cacheBreakpointAfter?: boolean;
21	}
22	
23	export interface BudgetReport {
24	  zoneA: number;
25	  zoneB: number;
26	  zoneC: number;
27	  tail: number;
28	  total: number;
29	  /** Zones that ran over their configured budget, after degradation attempts. */
30	  overBudget: Zone[];
31	  /** Summaries dropped to fit Zone B, oldest-first (never reordered). */
32	  droppedFromZoneB: NodeId[];
33	  /**
34	   * The host's context window, when the host supplied one, and what this prompt
35	   * leaves of it.
36	   *
37	   * This is the only real constraint in the report: a prompt that exceeds the
38	   * window fails at the provider, while a zone over its own share merely spent
39	   * an allocation someone chose. Until 2026-09-02 the assembler had no window
40	   * at all — it summed `total` and compared it to nothing — so "fits" could
41	   * only ever mean "fits a share of a number the library did not have". Both
42	   * fields are `null` when the host supplied no window, which is honest about
43	   * not knowing rather than assuming a default.
44	   */
45	  window: number | null;
46	  /** `window - total`, negative when the prompt cannot be sent. `null` if no window. */
47	  windowRemaining: number | null;
48	  /** True only when a window is known AND the prompt exceeds it. */
49	  overWindow: boolean;
50	  /**
51	   * What to pass as the provider's `max_tokens` this turn — the largest reply
52	   * that fits beside this prompt. `null` without a window.
53	   *
54	   * Per-turn arithmetic, not a chosen ceiling: early in a session it is nearly
55	   * the whole window, late in a long one it is small, and a session continues
56	   * on short replies where a fixed ceiling would have made the request invalid.
57	   */
58	  replyAllowance: number | null;
59	  /**
60	   * Tail entries omitted from THIS candidate so prompt + reply fit the window:
61	   * oldest acknowledged ephemeral payloads first. Held entries are removed only
62	   * when this candidate's delivery is acknowledged. Empty
63	   * when no window is known or nothing was over.
64	   */
65	  evictedFromTail: string[];
66	  /**
67	   * Zone C event blocks dropped, oldest first, when the tail alone could not
68	   * make room — the last valve, reported so a run that lost its own recent
69	   * detail says so.
70	   */
71	  droppedFromZoneC: number;
72	}
73	
74	export interface TailEntry {
75	  /** `context_fetch` / `context_search` / `context_peek` result text. */
76	  id: string;
77	  text: string;
