1	/**
2	 * ============================================================================
3	 * EXPERIMENT: flex-buffer assembler redesign — cache economics (offline)
4	 * ============================================================================
5	 *
6	 * Results: reports/metrics/assembler-flex-buffer/results.json
7	 *
8	 * PROPOSAL UNDER TEST (operator's redesign)
9	 * -----------------------------------------
10	 *  - Zone A grows to hold system + steering + ALL user prompts (append-only), so
11	 *    user intent is never evicted.
12	 *  - Zones B and C merge into ONE flex-fill buffer holding a varying mix of
13	 *    representations (single-line ref / summary / whole raw result) up to a soft
14	 *    target.
15	 *
16	 * THE QUESTION: does the cache economics close? Zone B is separate today ONLY for
17	 * cache stability (D5). A flex buffer that RE-PICKS its mix each turn rewrites the
18	 * cached prefix and pays cacheWrite (1.25x) every turn — the cache-killer. The
19	 * hypothesised fix is append-mostly + sticky representation + a secondary
20	 * breakpoint (layout R), so the buffer's head stays cached and only its tail
21	 * re-sends. This run measures that against the real multi-turn cache model.
22	 *
23	 * METHOD: a deterministic simulated session (units accrue; phases close; user
24	 * prompts arrive). For each design VARIANT, build the per-turn AssembledPrompt and
25	 * feed it to the SHIPPED ProviderCacheSimulator. Effective input cost per turn =
26	 * 0.1*cacheRead + 1.25*cacheWrite + 1.0*fresh (Anthropic multipliers, cost.ts).
27	 *
28	 * VARIANTS
29	 *  - current-zones      : Zone A frozen + Zone B (summaries, creation order, cached)
30	 *                         + Zone C (open phase raw, rewritten each turn). Today's shape.
31	 *  - flex-remix         : Zone A frozen + one buffer re-ranked by relevance each
32	 *                         turn (cache-death baseline — order churns after Zone A).
33	 *  - flex-append-sticky : Zone A = system+steering+all user prompts (append-only)
34	 *                         + flex buffer, creation order, sticky representation,
35	 *                         secondary breakpoint after the stable head, soft target.
36	 *
37	 * CAVEAT: synthetic session; token sizes are stylised. This measures the CACHE
38	 * MECHANICS (does the design invalidate the prefix, and what it costs), not task
39	 * quality — that is live-only. The relative ordering across variants is the result.
40	 * RERUN: node flex-buffer-cache.mjs   (needs @context-tree/core built)
41	 * ============================================================================
42	 */
43	import { writeFileSync, existsSync, mkdirSync } from 'node:fs';
44	import { execSync } from 'node:child_process';
45	import { fileURLToPath } from 'node:url';
46	import { dirname, join } from 'node:path';
47	
48	const HERE = dirname(fileURLToPath(import.meta.url));
49	const REPO = join(HERE, '..', '..');
50	const OUT_DIR = join(REPO, 'reports', 'metrics', 'assembler-flex-buffer');
51	const D = (p) => join(REPO, 'packages', 'core', 'dist', p);
52	const { HeuristicTokenizer } = await import(D('tokens/index.js'));
53	const { ProviderCacheSimulator } = await import(D('cache/index.js'));
54	function gitSha() { try { return execSync('git rev-parse HEAD', { cwd: REPO }).toString().trim(); } catch { return null; } }
55	
56	const W = 40000;
57	const TURNS = 50;
58	const UNITS_PER_PHASE = 5;
59	const USER_EVERY = 6;
60	const TOK = { system: 1000, tools: 2000, steering: 1500, userPrompt: 300, raw: 2000, summary: 200, ref: 20 };
61	const COST = { read: 0.1, write: 1.25, fresh: 1.0 }; // Anthropic multipliers (cost.ts)
62	
63	// SHARED CONTENT (identical across variants so only LAYOUT/order/breakpoints differ):
64	// closed-phase units render as summaries, the open phase's units render as raw,
65	// plus the user-prompt units. Variants place/order/pin/break these differently.
66	function contentBlocks(s) {
67	  const summaries = []; for (let p = 0; p < s.closedPhases; p++) summaries.push({ id: `sum:phase${p}`, tokens: TOK.summary });
68	  const raw = s.units.filter((u) => u.phase === s.openPhase).map((u) => ({ id: `raw:${u.id}`, tokens: TOK.raw }));
69	  const users = s.userPrompts.map((p) => ({ id: `user:${p}`, tokens: TOK.userPrompt }));
70	  return { summaries, raw, users };
71	}
72	
73	const text = (n) => `t${'ok '.repeat(Math.max(1, n))}`; // ~n tokens under HeuristicTokenizer
74	const blk = (zone, id, tokens) => ({ zone, id, text: text(tokens), tokens });
75	
76	// ---- simulated session state at turn t (0-based): units 0..t, phases, user prompts ----
77	function stateAt(t) {
78	  const units = []; for (let i = 0; i <= t; i++) units.push({ id: `u${i}`, phase: Math.floor(i / UNITS_PER_PHASE) });
79	  const openPhase = Math.floor(t / UNITS_PER_PHASE);
80	  const closedPhases = openPhase; // phases 0..openPhase-1 are closed
81	  const userPrompts = []; for (let i = 0; i * USER_EVERY <= t; i++) userPrompts.push(`p${i}`);
82	  return { units, openPhase, closedPhases, userPrompts };
83	}
84	
85	// ---- per-variant AssembledPrompt builders (SAME content, different layout) ----
86	// current-zones: [system,tools][summaries creation-order, cached][user prompts + open-phase raw, recent, re-sent]
87	function currentZones(t) {
88	  const s = stateAt(t); const c = contentBlocks(s);
89	  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:tools', TOK.tools)];
90	  const bp = ['A:tools'];
91	  for (const sm of c.summaries) blocks.push(blk('B', `B:${sm.id}`, sm.tokens));
92	  if (c.summaries.length) bp.push(`B:${c.summaries[c.summaries.length - 1].id}`);
93	  for (const u of c.users) blocks.push(blk('C', `C:${u.id}`, u.tokens)); // user prompts float in recent (not pinned)
94	  for (const r of c.raw) blocks.push(blk('C', `C:${r.id}`, r.tokens));
95	  return { blocks, cacheBreakpoints: bp };
96	}
97	// flex-remix: [system,tools][ALL content re-ranked by churning relevance each turn] — cache-death baseline
98	function flexRemix(t) {
99	  const s = stateAt(t); const c = contentBlocks(s);
100	  const all = [...c.users, ...c.summaries, ...c.raw];
101	  const order = all.map((b, i) => ({ b, r: (i * 7 + t * 13) % Math.max(1, all.length) }));
102	  order.sort((a, b) => a.r - b.r);
103	  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:tools', TOK.tools)];
104	  for (const { b } of order) blocks.push(blk('F', `F:${b.id}`, b.tokens));
105	  return { blocks, cacheBreakpoints: ['A:tools'] };
106	}
107	// flex-append-sticky: [system,steering,user prompts append-only][summaries+raw creation-order, secondary bp after stable head]
108	function flexAppendSticky(t, softFrac) {
109	  const s = stateAt(t); const c = contentBlocks(s);
110	  const blocks = [blk('A', 'A:system', TOK.system), blk('A', 'A:steering', TOK.steering)];
111	  for (const u of c.users) blocks.push(blk('A', `A:${u.id}`, u.tokens)); // user prompts pinned, append-only
112	  const bp = c.users.length ? [`A:${c.users[c.users.length - 1].id}`] : ['A:steering'];
113	  // Flex buffer, creation order: stable head = closed-phase summaries; volatile tail = open-phase raw.
114	  const stable = c.summaries.map((sm) => ({ id: `F:${sm.id}`, tokens: sm.tokens }));
115	  const volatile = c.raw.map((r) => ({ id: `F:${r.id}`, tokens: r.tokens }));
116	  // Soft target: bound the buffer by dropping the OLDEST stable summaries first (conservative: keep recent+raw).
117	  const soft = softFrac * W;
118	  let used = [...stable, ...volatile].reduce((x, b) => x + b.tokens, 0);
119	  while (used > soft && stable.length > 0) { used -= stable[0].tokens; stable.shift(); }
120	  for (const b of stable) blocks.push(blk('F', b.id, b.tokens));
121	  if (stable.length) bp.push(stable[stable.length - 1].id); // secondary breakpoint after stable head
122	  for (const b of volatile) blocks.push(blk('F', b.id, b.tokens));
123	  return { blocks, cacheBreakpoints: bp };
124	}
125	
126	function asPrompt(built) {
127	  return { system: '', blocks: built.blocks, cacheBreakpoints: built.cacheBreakpoints, budgets: {}, deliveryReceipt: { blocks: [] } };
128	}
129	
130	function runVariant(name, builder) {
131	  const tokenizer = new HeuristicTokenizer();
132	  const sim = new ProviderCacheSimulator({ tokenizer });
133	  let read = 0, write = 0, fresh = 0, peakTotal = 0;
134	  const perTurn = [];
135	  for (let t = 0; t < TURNS; t++) {
136	    const o = sim.submit(asPrompt(builder(t)));
137	    read += o.cacheRead; write += o.cacheWrite; fresh += o.fresh;
138	    peakTotal = Math.max(peakTotal, o.total);
139	    perTurn.push({ t, total: o.total, cacheRead: o.cacheRead, cacheWrite: o.cacheWrite, fresh: o.fresh, divergedInZone: o.divergedInZone });
140	  }
141	  const effective = COST.read * read + COST.write * write + COST.fresh * fresh;
142	  const naive = perTurn.reduce((s, x) => s + x.total, 0); // cost if nothing cached (all fresh)
143	  return { name, totalRead: read, totalWrite: write, totalFresh: fresh, effectiveInputCost: Math.round(effective),
144	    naiveCost: naive, cacheSavingsPct: +(100 * (1 - effective / naive)).toFixed(1), peakOccupancy: +(peakTotal / W).toFixed(3), perTurn };
145	}
146	
147	function main() {
148	  const variants = [
149	    runVariant('current-zones', currentZones),
150	    runVariant('flex-remix', flexRemix),
151	    runVariant('flex-append-sticky@0.4', (t) => flexAppendSticky(t, 0.4)),
152	    runVariant('flex-append-sticky@0.25', (t) => flexAppendSticky(t, 0.25)),
153	    runVariant('flex-append-sticky@0.5', (t) => flexAppendSticky(t, 0.5)),
154	  ];
155	  const out = {
156	    runId: process.env.RUN_ID ?? `assembler-flex-buffer-${new Date().toISOString().slice(0, 10)}`,
157	    armId: 'flex-buffer-cache@v1', offline: true, deterministic: true, model: null,
158	    commit: gitSha(), date: new Date().toISOString(),
159	    setup: { window: W, turns: TURNS, unitsPerPhase: UNITS_PER_PHASE, userEvery: USER_EVERY, tokens: TOK, costMultipliers: COST },
160	    simulator: 'shipped ProviderCacheSimulator (packages/core/src/cache)',
161	    caveat: 'Synthetic session; stylised token sizes. Measures CACHE MECHANICS (prefix invalidation + cost), not task quality (live-only). Relative ordering is the result.',
162	    variants: variants.map(({ perTurn, ...v }) => v),
163	    perTurnByVariant: Object.fromEntries(variants.map((v) => [v.name, v.perTurn])),
164	  };
165	  if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true });
166	  writeFileSync(join(OUT_DIR, 'results.json'), JSON.stringify(out, null, 2));
167	
168	  console.log(`session: ${TURNS} turns, W=${W} | cost = 0.1*read + 1.25*write + 1.0*fresh (Anthropic)`);
169	  console.log('\nvariant'.padEnd(26) + 'effCost'.padStart(10) + 'vsNaive'.padStart(9) + 'read'.padStart(9) + 'write'.padStart(9) + 'fresh'.padStart(9) + 'peakOcc'.padStart(9));
170	  for (const v of variants) {
171	    console.log(v.name.padEnd(26) + String(v.effectiveInputCost).padStart(10) + `${v.cacheSavingsPct}%`.padStart(9) +
172	      String(v.totalRead).padStart(9) + String(v.totalWrite).padStart(9) + String(v.totalFresh).padStart(9) + `${(v.peakOccupancy * 100).toFixed(0)}%`.padStart(9));
173	  }
174	  console.log('\neffCost = total effective input tokens over the session (lower = cheaper); vsNaive = % saved vs no cache.');
175	  console.log(`wrote ${join('reports', 'metrics', 'assembler-flex-buffer', 'results.json')}`);
176	}
177	
178	main();
179

