  const openPhase = Math.floor(t / UNITS_PER_PHASE);
  const closedPhases = openPhase; // phases 0..openPhase-1 are closed
  const userPrompts = []; for (let i = 0; i * USER_EVERY <= t; i++) userPrompts.push(`p${i}`);
