 *
 * The buffer only appends and evicts in place; it never re-mixes (re-ordering the
 * prefix is cache-death). Dormancy comes from the classifier (stage 1); this stage
 * consumes it and never computes embeddings itself.
 */
import type {
  AssembledPrompt,
  BudgetReport,
  NodeId,
  PromptBlock,
  Tokenizer,
} from '../contracts/index.js';
import { replyHeadroom } from './budgets.js';
import {
  planEviction,
  DEFAULT_EVICTION_WEIGHTS,
  type EvictionCandidate,
  type EvictionWeights,
} from './eviction.js';

/**
 * Soft-target floor `f`, as a fraction of the window: the buffer is evicted down
 * to this and never below it. Spec range 25–50%; the midpoint is the default.
 * PROVISIONAL — `f` is untested on a genuinely overflowing session
 * (`reports/session-handoff.md`, backlog item 7).
 */
export const DEFAULT_SOFT_TARGET_FRAC = 0.375;

/**
 * Recency anchor `A`: the last A units are kept raw and never evicted.
 * PROVISIONAL — introduced as a read-loop guard, never swept.
 */
export const DEFAULT_ANCHOR = 4;

/** Priority-decay half-life in turns (spec left the law open; exponential, ≈ A). PROVISIONAL. */
export const DEFAULT_PRIORITY_HALFLIFE = DEFAULT_ANCHOR;

export type Representation = 'raw' | 'summary';

/** One unit the assembler places. `dormancy` is the classifier's output (stage 1). */
export interface FlexUnit {
  nodeId: NodeId;
  /** Creation-order index; higher = newer. Units are supplied in ascending order. */
  order: number;
  fingerprints: ReadonlySet<string>;
  /** The phase wrote a file or was fetched → priority boost. */
  wrote: boolean;
  /** Turn index of the unit's last reference (for reference-recency + priority decay). */
  lastReferencedTurn: number;
  /** Continuous topic-shift dormancy from the classifier, higher = more dormant. */
  dormancy: number;
  /** The unit's full raw text (kept for the anchor / active phase). */
  raw: string;
  /** The unit's summary text, when it has been latched (older units fold to this). */
  summary?: string;
}

/** The frozen head: never evicted, append-only. */
export interface FlexHead {
  system: string;
  steering?: string;
  /** All user prompts, in order — append-only so user intent is never evicted. */
  userPrompts: readonly string[];
}

export interface FlexAssembleOptions {
  /** Host context window in tokens. Required for eviction (the floor is a fraction of it). */
  window: number;
  softTargetFrac?: number;
  anchor?: number;
  /** Reply reservation; defaults to `replyHeadroom({ window })`. */
  reserve?: number;
  weights?: EvictionWeights;
  /** Current turn index, for priority decay + reference-recency. Defaults to max unit order. */
  currentTurn?: number;
  /** Retrieved results to append after the buffer (untouched prefix). */
  tail?: readonly { id: string; text: string }[];
  priorityHalfLife?: number;
}

function sumTokens(blocks: readonly PromptBlock[]): number {
  return blocks.reduce((s, b) => s + b.tokens, 0);
}

/** Number of other units sharing at least one fingerprint (recurrence). */
function corecurrence(units: readonly FlexUnit[], i: number): number {
  const fp = units[i]!.fingerprints;
  let n = 0;
  for (let j = 0; j < units.length; j += 1) {
    if (j === i) continue;
    for (const f of fp) {
      if (units[j]!.fingerprints.has(f)) {
        n += 1;
        break;
      }
    }
  }
  return n;
}

/**
 * Assemble the flex prompt. Units MUST be supplied in creation order. Older units
 * fold to their summary (if present); the last `anchor` units + any that lack a
 * summary stay raw. Eviction removes the lowest-scoring non-anchor units until the
 * buffer fits the soft-target floor `f`.
 */
export function assembleFlex(
  head: FlexHead,
  units: readonly FlexUnit[],
  tokenizer: Tokenizer,
  options: FlexAssembleOptions,
): AssembledPrompt {
  const window = options.window;
  if (!Number.isFinite(window) || window <= 0) {
    throw new RangeError('window must be a finite positive number of tokens');
  }
  const anchor = options.anchor ?? DEFAULT_ANCHOR;
  const softFrac = options.softTargetFrac ?? DEFAULT_SOFT_TARGET_FRAC;
  const weights = options.weights ?? DEFAULT_EVICTION_WEIGHTS;
  const reserve = options.reserve ?? replyHeadroom({ window }).tokens;
  const halfLife = options.priorityHalfLife ?? DEFAULT_PRIORITY_HALFLIFE;
  const currentTurn = options.currentTurn ?? (units.length > 0 ? units[units.length - 1]!.order : 0);

  const block = (zone: PromptBlock['zone'], id: string, text: string, nodeId?: NodeId): PromptBlock => {
    const b: PromptBlock = { zone, id, text, tokens: tokenizer.count(text) };
    if (nodeId !== undefined) b.nodeId = nodeId;
    return b;
  };

  // ── frozen head: system + steering + all user prompts, append-only ──────────
  const headBlocks: PromptBlock[] = [block('head', 'head:system', head.system)];
  if (head.steering !== undefined && head.steering !== '') {
    headBlocks.push(block('head', 'head:steering', head.steering));
  }
  head.userPrompts.forEach((p, i) => headBlocks.push(block('head', `head:user:${i}`, p)));

  // ── representation: the last `anchor` units raw; older units fold to summary ─
  const n = units.length;
  const anchorFrom = Math.max(0, n - anchor);
  const repr = (i: number): Representation =>
    i >= anchorFrom || units[i]!.summary === undefined ? 'raw' : 'summary';
  const unitText = (i: number): string =>
    repr(i) === 'summary' ? units[i]!.summary! : units[i]!.raw;
  const unitTokens = (i: number): number => tokenizer.count(unitText(i));

  // ── eviction: score every non-anchor unit; keep down to the floor `f` ───────
  const candidates: EvictionCandidate[] = units.map((u, i) => {
    const decay = Math.pow(0.5, Math.max(0, currentTurn - u.lastReferencedTurn) / halfLife);
    return {
      index: i,
      tokens: unitTokens(i),
      anchor: i >= anchorFrom,
      signals: {
        priority: ((u.wrote ? 2 : 0) + corecurrence(units, i)) * decay,
        recency: u.order,
        refRecency: -(currentTurn - u.lastReferencedTurn),
        dormancy: u.dormancy,
      },
    };
  });
  const floor = Math.max(0, softFrac * window);
  const plan = planEviction(candidates, floor, weights);
  const keptIndices = new Set(plan.keep);

  // ── flex blocks, CREATION ORDER, kept units only (append-only, never remixed) ─
  // The stable run is the LEADING CONTIGUOUS run of summary blocks; the secondary
  // breakpoint falls after it. A raw block — an anchor OR an old unit whose summary
  // has not latched yet (summarization is async) — CLOSES the stable run, so a later
  // raw→summary latch can never rewrite a block inside the cached prefix. Placing the
  // breakpoint after the last summary *anywhere* would trap such a raw hole before it.
  const flexBlocks: PromptBlock[] = [];
  let lastStableId: string | null = null;
  let stableRunOpen = true;
  for (let i = 0; i < n; i += 1) {
    if (!keptIndices.has(i)) continue;
    const u = units[i]!;
    const isSummary = repr(i) === 'summary';
    const b = block('flex', `flex:${u.nodeId}`, unitText(i), u.nodeId);
    flexBlocks.push(b);
    if (stableRunOpen && isSummary) lastStableId = b.id;
    else if (!isSummary) stableRunOpen = false;
  }

  // ── tail: retrieved results, appended after the buffer ──────────────────────
  const tailEntries = options.tail ?? [];
  const tailBlocks = tailEntries.map((e) => block('tail', `tail:${e.id}`, e.text));

  // ── breakpoints: after the head, and after the stable (summary) run ─────────
  const cacheBreakpoints: string[] = [];
  const lastHead = headBlocks.at(-1);
  if (lastHead !== undefined) {
    lastHead.cacheBreakpointAfter = true;
    cacheBreakpoints.push(lastHead.id);
  }
  if (lastStableId !== null) {
    const stable = flexBlocks.find((b) => b.id === lastStableId)!;
    stable.cacheBreakpointAfter = true;
    cacheBreakpoints.push(stable.id);
  }

  const blocks = [...headBlocks, ...flexBlocks, ...tailBlocks];
  const headTokens = sumTokens(headBlocks);
  const flexTokens = sumTokens(flexBlocks);
  const tailTokens = sumTokens(tailBlocks);
  const total = headTokens + flexTokens + tailTokens;

  // BudgetReport is the legacy shape (its zoneA/B/C fields are renamed in the
  // final swap that removes ZoneAssembler): head → zoneA, flex → zoneB, zoneC 0.
  const budgets: BudgetReport = {
    zoneA: headTokens,
    zoneB: flexTokens,
    zoneC: 0,
    tail: tailTokens,
    total,
    overBudget: [],
    droppedFromZoneB: plan.evict.map((i) => units[i]!.nodeId),
    window,
    windowRemaining: window - total,
    // Contract meaning: the prompt itself exceeds the window (matches ZoneAssembler
    // and the BudgetReport doc). Reply room is reported separately via replyAllowance.
    overWindow: total > window,
    replyAllowance: Math.max(0, window - total),
    evictedFromTail: [],
    droppedFromZoneC: 0,
  };

  return {
    system: headBlocks.map((b) => b.text).join('\n\n'),
    blocks,
    budgets,
    cacheBreakpoints,
  };
}

/**
 * Eviction scoring (D-EV) — the SETTLED eviction *policy shape*.
 *
 * Provenance: the priority-dominant / relevance≈0 ordering is a settled result —
 * it won an offline head-to-head over real sessions at every budget and was once
 * confirmed live (−26% vs none / −14% vs recency at equal task success). See
 * `reports/metrics/assembler-weighting/report-assembler-weighting.md` (D-EV1–5)
 * and `reports/metrics/coding-harness/report-eviction.md`.
 *
 * What is settled is the SHAPE: priority dominates, recency and reference-recency
 * are protective, topic-dormancy subtracts, and query-relevance is weighted ZERO
 * (relevance is an *admission* signal, not an eviction one — on non-monotonic
 * history it drops exactly the dormant unit that later returns). What is NOT yet
 * settled is the exact coefficients: `DEFAULT_EVICTION_WEIGHTS` are the
 * hand-rounded D-EV defaults, and the sweep's own optimum differed
 * (`[rec .5, rel 0, prio .5, refrec 1]`), so treat them as tunable defaults, not
 * canon. `reports/session-handoff.md` → backlog item 2.
 */

/** Per-unit eviction signals, each a raw (un-normalized) magnitude. */
export interface EvictionSignals {
  /** Edit/fetch boost + fingerprint-recurrence, decayed by turns since last reference. Higher = keep. */
  priority: number;
  /** 1 − normalized age (turns since created). Higher = more recent = keep. */
  recency: number;
  /** 1 − normalized turns since the unit's fingerprints were last referenced. Higher = keep. */
  refRecency: number;
  /** The classifier's continuous topic-shift drift. Higher = more dormant = evict. */
  dormancy: number;
}

export interface EvictionWeights {
  priority: number;
  recency: number;
  refRecency: number;
  dormancy: number;
}

/**
 * The hand-rounded D-EV defaults. PROVISIONAL — the offline sweep's optimum was
 * `[recency .5, relevance 0, priority .5, refRecency 1]` and the LR rates put
 * priority far ahead (`prio 4.12 ≫ rec 2.42 ≈ rel 2.37 > refrec 1.04`); the
 * dormancy term is the classifier's contribution and is the least tuned. Refit
 * before hardcoding any of these as canon (handoff backlog item 2). Relevance is
 * absent by design (weight 0): it never enters eviction.
 */
export const DEFAULT_EVICTION_WEIGHTS: Readonly<EvictionWeights> = Object.freeze({
  priority: 2,
  recency: 1,
  refRecency: 0.5,
  dormancy: 1,
});

/** Min-max normalize to [0,1]; a flat vector maps to all-zeros (no signal). */
export function minMaxNormalize(values: readonly number[]): number[] {
  if (values.length === 0) return [];
  let lo = Infinity;
  let hi = -Infinity;
  for (const v of values) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  const span = hi - lo;
  if (span <= 0) return values.map(() => 0);
  return values.map((v) => (v - lo) / span);
}

/**
 * Score each candidate unit. Signals are min-max normalized ACROSS THE CURRENT
 * CANDIDATES this turn (per-turn normalization is part of the settled policy —
 * absolute magnitudes are not comparable across turns), then mixed linearly.
 * Higher score = keep; lower = evict first.
 */
export function scoreUnits(
  signals: readonly EvictionSignals[],
  weights: EvictionWeights = DEFAULT_EVICTION_WEIGHTS,
): number[] {
  if (signals.length === 0) return [];
  const priorityN = minMaxNormalize(signals.map((s) => s.priority));
  const recencyN = minMaxNormalize(signals.map((s) => s.recency));
  const refRecencyN = minMaxNormalize(signals.map((s) => s.refRecency));
  const dormancyN = minMaxNormalize(signals.map((s) => s.dormancy));
  return signals.map(
    (_, i) =>
      weights.priority * priorityN[i]! +
      weights.recency * recencyN[i]! +
      weights.refRecency * refRecencyN[i]! -
      weights.dormancy * dormancyN[i]!,
  );
}

export interface EvictionCandidate {
  /** Stable index/id of the unit in the caller's buffer. */
  index: number;
  signals: EvictionSignals;
  /** Token cost of keeping this unit raw/summarized in the buffer. */
  tokens: number;
  /** Pinned units (head, active phase) are never scored or evicted. */
  pinned?: boolean;
  /** Recency-anchor units are never evicted regardless of score. */
  anchor?: boolean;
}

export interface EvictionPlan {
  /** Indices to keep, in the caller's original order (creation order preserved). */
  keep: number[];
  /** Indices evicted this turn. */
  evict: number[];
  /** Total kept tokens after eviction (excludes pinned, which the caller accounts separately). */
  keptTokens: number;
}

/**
 * Decide what to keep to fit `budget` tokens. Eviction fires only when the
 * candidates exceed the budget (the soft-target floor `f` — never prune below
 * it); above it, evict the LOWEST-scoring first; anchors and pinned units are
 * always kept. Kept indices are returned in ascending (creation) order so the
 * caller re-emits the buffer append-only, never re-mixed (cache discipline).
 *
 * `budget` here is the space available to the flex buffer (the caller subtracts
 * the frozen head + reply reserve first). Anchors count against it but are never
 * dropped, matching the spec's "never drop the recency anchor".
 */
export function planEviction(
  candidates: readonly EvictionCandidate[],
  budget: number,
  weights: EvictionWeights = DEFAULT_EVICTION_WEIGHTS,
): EvictionPlan {
  const evictable = candidates.filter((c) => !c.pinned && !c.anchor);
  const alwaysKeep = candidates.filter((c) => c.pinned || c.anchor);
  const total = candidates.filter((c) => !c.pinned).reduce((s, c) => s + c.tokens, 0);

  const keepSet = new Set<number>(alwaysKeep.map((c) => c.index));
  let used = alwaysKeep.filter((c) => !c.pinned).reduce((s, c) => s + c.tokens, 0);

  // Below the floor: keep everything.
  if (total <= budget) {
    for (const c of evictable) {
      keepSet.add(c.index);
      used += c.tokens;
    }
  } else {
    const scores = scoreUnits(evictable.map((c) => c.signals), weights);
    // Highest score first; fill until the next unit would exceed the budget.
    const order = evictable
      .map((c, i) => ({ index: c.index, tokens: c.tokens, score: scores[i]! }))
      .sort((a, b) => b.score - a.score);
    for (const c of order) {
      if (used + c.tokens <= budget) {
        keepSet.add(c.index);
        used += c.tokens;
      }
    }
  }

  const keep = candidates
    .map((c) => c.index)
    .filter((i) => keepSet.has(i))
    .sort((a, b) => a - b);
  const evict = candidates
    .map((c) => c.index)
    .filter((i) => !keepSet.has(i))
    .sort((a, b) => a - b);
  return { keep, evict, keptTokens: used };
}

