1	/**
2	 * §9 `context_search` — collapsed-tree (RAPTOR) retrieval over node-summary
3	 * vectors, falling back to beam search over summary TEXT when L3 is absent, and
4	 * fanning out to the §9.1 providers when a registry is wired.
5	 *
6	 * §19 Q2, revised 2026-09-04: the RANKING is over summaries (fingerprint-enriched,
7	 * grep re-ranked), but the HIT is an event — the best-matching raw events across
8	 * the ranked branches, each with its seq and an excerpt of its own text. Measured
9	 * 15/25 vs 6/25 against branch coordinates, every success with zero fetches
10	 * (`reports/metrics/window-regime-and-retrieval-unit-report.md` §7). `context_fetch` /
11	 * `context_peek` remain the way to read more than the excerpt.
12	 */
13	import { z } from 'zod';
14	import {
15	  mergeCandidates,
16	  type Candidate,
17	  type EventHit,
18	  type MergeResult,
19	  type NodeId,
20	  type NodeKind,
21	  type PhaseType,
22	  type ProviderOutcome,
23	  type ProviderTier,
24	  type SearchPath,
25	  type SummaryHit,
26	} from '@context-tree/core';
27	import { failFrom, ok, parseArgs } from '../result.js';
28	import { recordRetrieval } from '../observe.js';
29	import type { ToolContext, ToolOutcome } from '../types.js';
30	
31	export const CONTEXT_SEARCH = 'context_search';
32	
33	/**
34	 * The tree's own hits enter the §9.1 merge under this id. Not `vector`: a
35	 * registry may also hold `createVectorProvider`, and two outcomes sharing an id
36	 * would collapse two distinct contributions into one provenance row. Duplicate
37	 * node hits are then deduped by `mergeCandidates` on `node_id`.
38	 */
39	const TREE_PROVIDER = 'tree';
40	
41	
42	export const CONTEXT_SEARCH_DESCRIPTION =
43	  'Search this task\'s recorded history. Reach for it when you know WHAT you need but not WHERE it ' +
44	  'happened — before re-deriving a decision, re-reading a file another phase already changed, or ' +
45	  'answering anything that must reproduce a literal. Each hit is one recorded EVENT: the branch it ' +
46	  'belongs to (node_id, title, meta pointers), its position (`seq`), and an `excerpt` of that ' +
47	  'event\'s own text. If the excerpt already shows the exact literal you need, answer from it. ' +
48	  'Otherwise call context_fetch with the hit\'s node_id as branch_id and `from`/`to` a few events ' +
49	  'either side of `seq` — that is the cheap read; a whole branch is the expensive one.';
50	
51	const shape = {
52	  query: z.string().min(1).describe('What you are looking for: a few content words or identifiers that appeared in the work, not a question.'),
53	  kind: z
54	    .enum(['task', 'phase', 'file', 'turn'])
55	    .optional()
56	    .describe("Narrow the answer to one node kind — 'file' to find which branch touched a path."),
57	};
58	
59	export const contextSearchSchema = z.object(shape);
60	export const contextSearchInputShape = shape;
61	
62	export interface SearchHitPayload {
63	  node_id: NodeId;
64	  kind: NodeKind;
65	  title: string;
66	  phase_type: PhaseType | null;
67	  path: string | null;
68	  summary_version: number;
69	  /** Event relevance for an event hit; the branch score for a bare coordinate. */
70	  score: number;
71	  /** 1-based rank of the hit's branch in the underlying branch search. */
72	  branch_rank: number;
73	  /** L0 event number the hit names, or null for a bare branch coordinate. */
74	  seq: number | null;
75	  /**
76	   * The hit's payload: a slice of the event's own rendered text; null for a bare
77	   * coordinate. This replaces the pointer `meta` a branch hit used to carry: on
78	   * the measured store a phase's file-span records ran to thousands of tokens
79	   * per hit list (the reason the compact-coordinate arm existed), and the
80	   * excerpt is what makes a hit legible now. The §8 metadata is one
81	   * context_fetch away.
82	   */
83	  excerpt: string | null;
84	}
85	
86	export interface ContextSearchData {
87	  query: string;
88	  /** Which mechanism answered, so §15's eval attributes recall to it. */
89	  path: SearchPath;
90	  /** Set only when the vector path was unavailable. */
91	  fallback: string | null;
92	  hits: SearchHitPayload[];
93	  /** Tree hits + §9.1 provider hits under §9.1's fixed tier order. */
94	  candidates: Candidate[];
95	  /** Per-provider kept/dropped — which tier actually contributed. */
96	  provenance: Array<{ provider: string; tier: ProviderTier; kept: number; dropped: number }>;
97	  /** Providers that failed their capability probe or threw. Degraded, never fatal (§18). */
98	  unavailable: string[];
99	}
100	
101	
102	function toHitPayload(hit: EventHit): SearchHitPayload {
103	  return {
104	    node_id: hit.nodeId,
105	    kind: hit.kind,
106	    title: hit.title,
107	    phase_type: hit.phaseType,
108	    path: hit.path ?? null,
109	    summary_version: hit.version,
110	    score: hit.score,
111	    branch_rank: hit.branchRank,
112	    seq: hit.seq,
113	    excerpt: hit.excerpt,
114	  };
115	}
116	
117	/** Mirrors `createVectorProvider`'s mapping: `path`/`span` only when a §8 pointer backs both. */
118	function toCandidate(hit: SummaryHit): Candidate {
119	  const file = hit.path === undefined ? undefined : hit.meta?.files.find((entry) => entry.path === hit.path);
120	  return {
121	    node_id: hit.nodeId,
122	    path: hit.path,
123	    span: file === undefined ? undefined : { start_line: file.start_line, end_line: file.end_line },
124	    symbol: hit.meta?.symbols?.[0],
125	    score: hit.score,
126	    provider: TREE_PROVIDER,
127	    tier: 'fuzzy',
128	    snippet: hit.text.slice(0, 240),
129	  };
130	}
131	
132	/**
133	 * Regroups the registry's already-merged candidates by provider so the tree can
134	 * be folded in under the same fixed order. The registry owns probing, timeouts
135	 * and failure isolation, so its merged list is the only view of the fan-out
136	 * available — and re-merging is safe because `mergeCandidates` is a total,
137	 * machine-independent sort.
138	 */
139	function providerOutcomes(fanout: MergeResult): ProviderOutcome[] {
140	  const byId = new Map<string, ProviderOutcome>();
141	  for (const candidate of fanout.candidates) {
142	    const existing = byId.get(candidate.provider);
143	    if (existing === undefined) {
144	      byId.set(candidate.provider, { provider: candidate.provider, tier: candidate.tier, candidates: [candidate] });
145	      continue;
146	    }
