  const recorded = node.span_end_seq ?? from;
  const to = node.status === 'open' ? Math.max(recorded, trace.lastSeq()) : recorded;
  const parts: string[] = [];
  for (const event of trace.read({ from, to })) parts.push(renderEvent(event, blobs));
  return parts.join('\n');
