      nodeId: node.id,
      order,
      rawText: nodeRawText(node, trace, blobs),
      ...(summary !== null ? { summaryText: summary.text } : {}),
      wrote,
      lastReferencedTurn: order,
    };
  });

  const { units, corpus } = await mapFlexUnits(entries, options);
  return { head, units, corpus };
