import { describe, it, expect } from 'vitest';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { openTaskStore, resolveConfig, TreeRetriever } from '@context-tree/core';
import { createServer } from '@context-tree/mcp';

describe('_probe: isolate the mcp worker crash', () => {
  it('a: bare test passes', () => {
    expect(1 + 1).toBe(2);
  });

  it('e: full MCP server + client connect over InMemoryTransport, listTools, close', async () => {
    const root = mkdtempSync(join(tmpdir(), 'ct-probe-'));
    const config = resolveConfig({ root, taskTitle: 'probe' });
    const handle = openTaskStore(config);
    const retriever = new TreeRetriever({ store: handle.store, blobs: handle.blobs, trace: handle.trace });
    const server = createServer({ config, handle, retriever, mode: 'tool-backend' });
    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    const client = new Client({ name: 'probe', version: '0.0.0' });
    await Promise.all([server.connect(serverTransport), client.connect(clientTransport)]);
    const { tools } = await client.listTools();
    expect(tools.length).toBeGreaterThan(0);
    await client.close();
    await server.close();
    handle.close();
