1	/**
2	 * Zone allowances derived from ONE number: the host's context window.
3	 *
4	 * Why this file exists. Until 2026-09-02 the library carried two independent
5	 * constants — a Zone B allowance of 8,000 tokens and a Zone C allowance of
6	 * 30,000 — with no representation of the window anywhere, so nothing could
7	 * check either against the constraint that actually matters. "The largest fold
8	 * level whose Zone B fits" was therefore fitting to a share of a number the
9	 * library did not have. The portability rules this project is held to call that
10	 * a defect twice over: it is a budget (rule 1) and it is a constant nobody
11	 * validated off the host it was fitted on (rule 2).
12	 *
13	 * What replaces it. The host supplies its window; these fractions partition it;
14	 * one function does the arithmetic. That does not make the fractions right —
15	 * they are still a design allocation and rule 4 says which allocation wins has
16	 * to be measured — but it makes them ONE thing derived from a real quantity
17	 * rather than several unrelated guesses, and it gives the assembler a window to
18	 * report the true constraint against.
19	 *
20	 * The tokenizer divisor. The assembler counts with a heuristic tokenizer while
21	 * the provider bills its own, and on real corpora those disagree by a
22	 * measurable factor. Handing the assembler `0.20 * W` would make the real
23	 * prompt `0.20 * W * ratio`, off by however far the heuristic drifts. Dividing
24	 * by the measured ratio makes the real prompt `0.20 * W`, which is the number
25	 * the window is expressed in. The ratio is measured per corpus by the caller;
26	 * this function only applies it.
27	 */
28	
29	/**
30	 * Shares of the window, summing to 1. Not validated: no experiment has swept
31	 * them, so they are an unvalidated design allocation and rule 2 marks them as
32	 * such. They are recorded here, in one place, so a sweep has something single
33	 * to vary.
34	 *
35	 * `switchPoint` is deliberately the same share as `zoneC`, not a separate
36	 * number. The rule it implements — summarize nothing while the whole trace
37	 * still fits where the active branch's detail would go — makes them the same
38	 * quantity by its own wording. They had drifted apart (0.35 against 0.20) in
39	 * the one harness that derived them at all, which is what that drift looks
40	 * like when two authors edit one occurrence.
41	 */
42	export const ZONE_FRACTIONS = Object.freeze({
43	  zoneA: 0.1,
44	  zoneB: 0.2,
45	  zoneC: 0.2,
46	  /**
47	   * FALLBACK ONLY. Reply headroom should come from the model, not from a share
48	   * — see `replyHeadroom`. This fraction applies when the host cannot say what
49	   * its model may emit, and it is a guess in exactly the way rule 2 forbids.
50	   */
51	  reply: 0.05,
52	  slack: 0.1,
53	  get switchPoint(): number {
54	    return 0.2;
55	  },
56	});
57	
58	/**
59	 * Room left in the window so the model's answer can arrive.
60	 *
61	 * **The algorithm requires this**, and it is not a reply cap. Prompt plus reply
62	 * must fit the window — that is arithmetic, and if the prompt crowds the reply
63	 * out the provider truncates the answer and reports it as a length stop. What
64	 * the algorithm does NOT require, and what was removed on 2026-09-02, is a
65	 * limit on how much the model may say: that is a guess about the work, and on a
66	 * model that reasons before answering it can be spent thinking, leaving an
67	 * empty reply that a grader scores as wrong.
68	 *
69	 * So the reservation stays and the ceiling goes. The size of the reservation
70	 * comes from the model: every provider reports the largest completion it will
71	 * emit, and reserving that is the only figure that cannot be too small. Rule 3
72	 * permits exactly this — a parameter set from a model's limits, obtained by
73	 * asking rather than by guessing.
74	 *
75	 * `observedMax` refines it downward. Reserving a 64,000-token maximum on a
76	 * 200,000-token window spends a third of the window on an answer no task in
77	 * this corpus has ever produced, so a caller that has measured its own replies
78	 * may pass the largest it has actually seen, with margin. That is rule 4's
79	 * sweet spot rather than rule 1's cap, because exceeding it costs a truncated
80	 * answer that is reported, not a silently degraded one.
81	 *
82	 * @param modelMaxOutput the largest completion the provider says it will emit
83	 * @param observedMax    the largest reply this caller has actually measured
84	 * @param window         used only for the fallback share, when nothing is known
85	 */
86	export function replyHeadroom(input: {
87	  modelMaxOutput?: number;
88	  observedMax?: number;
89	  window?: number;
90	}): { tokens: number; source: 'observed' | 'model-max' | 'window-fraction' } {
91	  const { modelMaxOutput, observedMax, window } = input;
92	  if (observedMax !== undefined && Number.isFinite(observedMax) && observedMax > 0) {
93	    // Never reserve more than the model could emit even if asked for more.
94	    const bounded =
95	      modelMaxOutput !== undefined && modelMaxOutput > 0 ? Math.min(observedMax, modelMaxOutput) : observedMax;
96	    return { tokens: Math.ceil(bounded), source: 'observed' };
97	  }
98	  if (modelMaxOutput !== undefined && Number.isFinite(modelMaxOutput) && modelMaxOutput > 0) {
99	    return { tokens: Math.ceil(modelMaxOutput), source: 'model-max' };
100	  }
101	  if (window !== undefined && Number.isFinite(window) && window > 0) {
102	    return { tokens: Math.floor(ZONE_FRACTIONS.reply * window), source: 'window-fraction' };
103	  }
104	  throw new RangeError(
105	    'replyHeadroom needs one of modelMaxOutput (preferred), observedMax, or window — ' +
106	      'the algorithm requires headroom for the reply and this library will not invent it',
107	  );
108	}
109	
110	export interface ZoneBudgets {
111	  /** The window these were derived from, carried so a report can name it. */
112	  window: number;
113	  /** The heuristic-to-provider ratio applied. 1 means no correction. */
114	  ratio: number;
115	  zoneA: number;
116	  zoneB: number;
117	  zoneC: number;
118	  /** Prompt size at which the tree stops showing the whole trace (= zoneC). */
119	  switchPoint: number;
120	  /** Reserved so a reply fits beside the prompt. NOT a limit on the reply. */
121	  reply: number;
122	  slack: number;
123	}
124	
125	/**
126	 * @param window the host's context window in provider tokens
127	 * @param ratio  measured heuristic-to-provider token ratio for this corpus
128	 */
129	export function deriveZoneBudgets(window: number, ratio = 1): ZoneBudgets {
130	  if (!Number.isFinite(window) || window <= 0) {
131	    throw new RangeError(`window must be a positive number of tokens, got ${String(window)}`);
132	  }
133	  if (!Number.isFinite(ratio) || ratio <= 0) {
134	    throw new RangeError(`ratio must be positive, got ${String(ratio)}`);
135	  }
136	  const per = (fraction: number): number => Math.floor((fraction * window) / ratio);
137	  return {
138	    window,
139	    ratio,
140	    zoneA: per(ZONE_FRACTIONS.zoneA),
141	    zoneB: per(ZONE_FRACTIONS.zoneB),
142	    zoneC: per(ZONE_FRACTIONS.zoneC),
143	    switchPoint: per(ZONE_FRACTIONS.switchPoint),
144	    reply: per(ZONE_FRACTIONS.reply),
145	    slack: per(ZONE_FRACTIONS.slack),
146	  };
147	}
148	
149	/**
150	 * What Zone B may actually occupy: everything the window has left once the
151	 * fixed contract, the active branch's detail, the appended tail and the reply
152	 * reservation are accounted for.
153	 *
154	 * This is the answer to "fit against what?" that does not invent a share. A
155	 * caller with a window should prefer it to `ZoneBudgets.zoneB`, because a
156	 * summary block that fits the remainder is one the prompt can actually carry,
157	 * while one that fits 20% of the window may still overflow — and, conversely, a
158	 * block rejected for exceeding its 20% share may have had room all along. The
159	 * latter is not hypothetical: on the one measured store, six of seven fold
160	 * levels satisfied the share test, so the share was barely binding and the
161	 * choice between them fell to a hand-written ordering instead.
162	 *
163	 * Never negative: a caller gets 0 and the knowledge that nothing fits.
164	 */
165	export function zoneBRemainder(input: {
166	  window: number;
167	  zoneA: number;
168	  zoneC: number;
169	  tail?: number;
170	  reply?: number;
171	}): number {
172	  const { window, zoneA, zoneC, tail = 0, reply = 0 } = input;
173	  return Math.max(0, window - zoneA - zoneC - tail - reply);
174	}
175	
176	/**
177	 * What to pass as the provider's `max_tokens` on THIS turn: whatever the window
178	 * has left once the assembled prompt is accounted for.
179	 *
180	 * This is the honest form of a reply limit, and it is not the thing rule 1
181	 * forbids. A fixed ceiling is a guess about how much the model needs to say. An
182	 * allowance computed per turn is arithmetic: the request either fits or it
183	 * fails, and this is the largest reply that fits. Nobody chose it.
184	 *
185	 * What it buys is the behaviour a fixed ceiling cannot have. Early in a session
186	 * the prompt is small and the allowance is nearly the whole window, so the model
187	 * may answer at length. Late in a long session the prompt is large and the
188	 * allowance is small, so the model answers briefly — and the session CONTINUES,
189	 * where a fixed ceiling would have made the request invalid and ended it. A
190	 * small-window model can therefore iterate through a long session on short
191	 * replies instead of failing at the point its prompt outgrew its ceiling.
192	 *
193	 * Sending it also tells the model its own allowance, which a prompt sentence
194	 * cannot do reliably: providers surface `max_tokens` to the model and stop at
195	 * it, so the model shortens its answer rather than being cut mid-sentence.
196	 *
197	 * The shrinking allowance is itself a signal, and it is the same quantity the
198	 * switch point is about: when the room left for an answer stops being enough
199	 * for a useful one, the prompt — not the answer — is what has to give. Callers
200	 * get the number and decide; this function does not pick a floor, because "a
201	 * useful reply" is task-shaped and picking one here would smuggle back the
202	 * constant this whole module exists to remove.
203	 *
204	 * @param window      the host's context window in provider tokens
205	 * @param promptTokens the assembled prompt's size, in the same units
206	 * @param modelMaxOutput the largest completion the provider will emit, if known
207	 */
208	export function replyAllowance(input: {
209	  window: number;
210	  promptTokens: number;
211	  modelMaxOutput?: number;
212	}): { tokens: number; limitedBy: 'window' | 'model' | 'none' } {
213	  const { window, promptTokens, modelMaxOutput } = input;
214	  if (!Number.isFinite(window) || window <= 0) {
215	    throw new RangeError(`window must be a positive number of tokens, got ${String(window)}`);
216	  }
217	  const room = Math.max(0, Math.floor(window - promptTokens));
218	  if (modelMaxOutput === undefined || !Number.isFinite(modelMaxOutput) || modelMaxOutput <= 0) {
219	    return { tokens: room, limitedBy: room === 0 ? 'window' : 'none' };
220	  }
221	  // Asking for more than the model can emit is not an error, but reporting
222	  // which side bound the allowance tells a caller whether a longer answer is
223	  // available by shrinking the prompt (window) or not at all (model).
224	  return room <= modelMaxOutput
225	    ? { tokens: room, limitedBy: 'window' }
226	    : { tokens: Math.floor(modelMaxOutput), limitedBy: 'model' };
227	}
