1	/**
2	 * §10 prompt assembly — layered lifecycle layout (D5). The layout is fixed;
3	 * content migrates through it by lifecycle. Zone B is never relevance-ordered:
4	 * reordering the cached prefix is the cache killer.
5	 */
6	import type { NodeId } from './ids.js';
7	
8	/**
9	 * Prompt regions, in prefix order. `head` / `flex` are the current (flex-buffer)
10	 * model — a frozen head (system + steering + all user prompts) then a
11	 * creation-order flex buffer of units; `tail` holds retrieved results appended
12	 * after it. `A` / `B` / `C` are the SUPERSEDED Zone A/B/C model kept only until
13	 * `ZoneAssembler` is removed (its layout was tested-and-lost on cache economics —
14	 * see `reports/metrics/assembler-flex-buffer/report.md`). New code uses
15	 * `head` / `flex` / `tail`. Ordering below satisfies both models (a prompt uses
16	 * one vocabulary or the other, never both).
17	 */
18	export type Zone = 'head' | 'flex' | 'A' | 'B' | 'C' | 'tail';
19	
20	export const ZONES: readonly Zone[] = ['head', 'flex', 'A', 'B', 'C', 'tail'] as const;
21	
22	export interface PromptBlock {
23	  zone: Zone;
24	  /** Stable within a zone across turns — cache assertions key on this. */
25	  id: string;
26	  text: string;
27	  tokens: number;
28	  nodeId?: NodeId;
29	  /** Provider cache breakpoint emitted after this block (§10 rule 5). */
30	  cacheBreakpointAfter?: boolean;
31	}
32	
33	export interface BudgetReport {
34	  zoneA: number;
35	  zoneB: number;
36	  zoneC: number;
37	  tail: number;
38	  total: number;
39	  /** Zones that ran over their configured budget, after degradation attempts. */
40	  overBudget: Zone[];
41	  /** Summaries dropped to fit Zone B, oldest-first (never reordered). */
42	  droppedFromZoneB: NodeId[];
43	  /**
44	   * The host's context window, when the host supplied one, and what this prompt
45	   * leaves of it.
46	   *
47	   * This is the only real constraint in the report: a prompt that exceeds the
48	   * window fails at the provider, while a zone over its own share merely spent
49	   * an allocation someone chose. Until 2026-09-02 the assembler had no window
50	   * at all — it summed `total` and compared it to nothing — so "fits" could
51	   * only ever mean "fits a share of a number the library did not have". Both
52	   * fields are `null` when the host supplied no window, which is honest about
53	   * not knowing rather than assuming a default.
54	   */
55	  window: number | null;
56	  /** `window - total`, negative when the prompt cannot be sent. `null` if no window. */
57	  windowRemaining: number | null;
58	  /** True only when a window is known AND the prompt exceeds it. */
59	  overWindow: boolean;
60	  /**
61	   * What to pass as the provider's `max_tokens` this turn — the largest reply
62	   * that fits beside this prompt. `null` without a window.
63	   *
64	   * Per-turn arithmetic, not a chosen ceiling: early in a session it is nearly
65	   * the whole window, late in a long one it is small, and a session continues
66	   * on short replies where a fixed ceiling would have made the request invalid.
67	   */
68	  replyAllowance: number | null;
69	  /**
70	   * Tail entries omitted from THIS candidate so prompt + reply fit the window:
71	   * oldest acknowledged ephemeral payloads first. Held entries are removed only
72	   * when this candidate's delivery is acknowledged. Empty
73	   * when no window is known or nothing was over.
74	   */
75	  evictedFromTail: string[];
76	  /**
77	   * Zone C event blocks dropped, oldest first, when the tail alone could not
78	   * make room — the last valve, reported so a run that lost its own recent
79	   * detail says so.
80	   */
81	  droppedFromZoneC: number;
82	}
83	
84	export interface TailEntry {
85	  /** `context_fetch` / `context_search` / `context_peek` result text. */
86	  id: string;
87	  text: string;
88	  /** Eligible for offloading after delivery has been acknowledged (D6). */
89	  ephemeral: boolean;
90	}
91	
92	/** Identity of the selected, rendered payload, not of its full source response. */
93	export interface DeliveredBlock {
94	  readonly id: string;
95	  /** SHA-256 of the exact UTF-8 block text. */
96	  readonly contentHash: string;
97	}
98	
99	/**
100	 * A delivery candidate. Creating this receipt acknowledges nothing. The host
101	 * acknowledges it only after successfully sending these exact selected blocks;
102	 * previews, failed calls, and requests that replace/cut blocks must not use it.
103	 * Receipts can be journalled beside requests without modifying L0 or L1.
104	 */
105	export interface DeliveryReceipt {
106	  readonly version: 1;
107	  readonly blocks: readonly DeliveredBlock[];
108	  readonly tailSource: 'internal' | 'supplied';
109	  /** Already-delivered tail payloads omitted from this candidate. */
110	  readonly evictedTail: readonly DeliveredBlock[];
