    expect(replyAllowance({ window: 8_192, promptTokens: 9_000 })).toEqual({
      tokens: 0,
      limitedBy: 'window',
    });
  });

  it('refuses a missing window rather than inventing one', () => {
    expect(() => replyAllowance({ window: 0, promptTokens: 10 })).toThrow(RangeError);
  });
