/**
 * LIVE, opt-in (§17): the same pipeline as `test/e2e.test.ts`, against a real
 * model. A canary, not a benchmark — one small trace on the cheap model,
 * capped by a `CostMeter`, because it spends the user's money on every run.
 *
 * What only a real model can tell us: whether §8's output contract actually
 * holds when nobody is stubbing it. The offline e2e proves the *plumbing*
 * carries pointers; a compliant stub cannot prove that a frontier model reads
 * `leaf-summary.v1.md`, replies with every required field, echoes the node ids
 * it was handed, and stays inside the branch's file whitelist. That is the
 * failure this test exists to catch — a prompt edit that quietly makes the
 * contract unfollowable passes every offline test in the repo.
 *
 * KNOWN RED as of the first runs of this file (2026-03, `claude-haiku-4-5`):
 * one leaf per run fails on its model-authored `meta.files[]` — observed
 * `start_line: missing required field`, `symbol: expected a non-empty string`,
 * and a path outside the branch whitelist, on three consecutive runs. The
 * retry does not recover it. Every one of those rejections is over a field
 * `summaryMetaFrom` DISCARDS (D9: stored spans come from tree-sitter), so a
 * branch is being dropped from the tree over data the system never keeps. That
 * is a defect in `prompts/parseSummaryResponse` + `summarize/contract.ts`, not
 * flake and not this test's assertion being too strict — do not relax it to get
 * a green run; the point of a canary is that it is red when the bird is dead.
 *
 * Costs a few cents. Run with:
 *   LIVE=1 npx vitest run packages/core/test/live
 */
import { afterAll, describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadApiKeys, loadDotEnv, resolveConfig } from '../../src/config.js';
import { AnthropicProvider, InMemoryCostMeter, OpenRouterProvider } from '../../src/models/index.js';
import { HeuristicTokenizer } from '../../src/tokens/index.js';
import { assembleFlex, buildFlexSource } from '../../src/assemble/index.js';
import { systemContract } from '../../src/prompts/index.js';
import { Summarizer } from '../../src/summarize/index.js';
import { ingest, openTaskStore } from '../../src/ingest/index.js';
import { TreeRetriever } from '../../src/retrieve/index.js';
import type {
  AssistantMessageEvent,
  ModelProvider,
  ToolCallEvent,
  ToolResultEvent,
  TraceEventInput,
  UserMessageEvent,
} from '../../src/contracts/index.js';
import { CONTEXT_FETCH, HANDLERS } from '@context-tree/mcp';
import type { ContextFetchData, ToolContext, ToolName } from '@context-tree/mcp';

loadDotEnv();
const keys = loadApiKeys();
const provider: 'anthropic' | 'openrouter' | null = keys.anthropic
  ? 'anthropic'
  : keys.openrouter
    ? 'openrouter'
    : null;
const enabled = Boolean(process.env.LIVE) && provider !== null;

/** §8's cheap leaf model in both roles: this is a contract canary, not a quality bar. */
const MODEL = provider === 'openrouter' ? 'anthropic/claude-haiku-4.5' : 'claude-haiku-4-5-20251001';

/**
 * §16's per-run cap. Four haiku calls over a ten-event trace are well under a
 * cent; the cap sits two orders of magnitude above that so it fires on a
 * runaway (a retry storm, a model id that silently routes to an expensive
 * tier) rather than on normal variance.
 */
const CAP_USD = 0.1;

const TS = '2026-03-02T09:00:00.000Z';
const PRICING = 'src/pricing.ts';
const FIX_MARKER = 'Math.round';
const PASSING_TEST = 'rounds half up on discounted totals';

const PRICING_BEFORE = [
  'export function price(cents: number, rate: number): number {',
  '  return Math.floor(cents * rate);',
  '}',
  '',
].join('\n');

const PRICING_AFTER = PRICING_BEFORE.replace('Math.floor', FIX_MARKER);

/** Per-variant factories: the bare `TraceEventInput` union erases `tool`/`blob` (see trace/index.ts). */
const userMessage = (blob: string): TraceEventInput<UserMessageEvent> => ({ type: 'user_message', ts: TS, blob });
const assistantMessage = (blob: string): TraceEventInput<AssistantMessageEvent> => ({
  type: 'assistant_message',
  ts: TS,
  blob,
});
const toolCall = (
  overrides: Partial<TraceEventInput<ToolCallEvent>> & { tool: string },
): TraceEventInput<ToolCallEvent> => ({ type: 'tool_call', ts: TS, ...overrides });
const toolResult = (
  overrides: Partial<TraceEventInput<ToolResultEvent>> & { call_seq: number },
): TraceEventInput<ToolResultEvent> => ({ type: 'tool_result', ts: TS, ...overrides });

const temps: string[] = [];
afterAll(() => {
  while (temps.length > 0) rmSync(temps.pop() ?? '', { recursive: true, force: true });
});

function liveProvider(): ModelProvider {
  if (provider === 'openrouter') return new OpenRouterProvider({ apiKey: keys.openrouter ?? '' });
  return new AnthropicProvider({ apiKey: keys.anthropic ?? '' });
}

describe.skipIf(!enabled)('live: a real model resumes a task from the tree', () => {
  it("writes §8-compliant summaries whose file pointers are the tree's, and resumes in one tool call", async () => {
    const dir = mkdtempSync(join(tmpdir(), 'ct-live-resume-'));
    temps.push(dir);
    const config = resolveConfig({
      root: dir,
      taskTitle: 'fix discounted invoice rounding',
      provider: provider ?? 'anthropic',
      leafModel: MODEL,
      rootModel: MODEL,
    });
    const handle = openTaskStore(config);
    const { blobs, store, trace } = handle;
    const meter = new InMemoryCostMeter({ capUsd: CAP_USD });

    try {
      // One diagnosis / implementation / verification arc. Deliberately tiny:
      // every line of it is billed on every run.
      trace.appendAll([
        userMessage(blobs.put('Discounted invoice lines round down a cent.')),
        toolCall({ tool: 'Read', path: PRICING, args_blob: blobs.put(`{"path":"${PRICING}"}`) }),
        toolResult({ call_seq: 2, output_blob: blobs.put(PRICING_BEFORE) }),
        toolCall({ tool: 'Edit', path: PRICING, blob: blobs.put(PRICING_AFTER) }),
        toolResult({ call_seq: 4, output_blob: blobs.put(`edited ${PRICING}`) }),
        toolCall({ tool: 'run_tests', args_blob: blobs.put('{"suite":"pricing"}') }),
        toolResult({
          call_seq: 6,
          output_blob: blobs.put(`PASS test/pricing.test.ts > ${PASSING_TEST}\n12 passing, 0 failing`),
        }),
        assistantMessage(blobs.put('Rounding now uses half-up; the suite is green.')),
      ]);
      ingest({ handle });

      const root = store.root();
      if (root === null) throw new Error('ingest produced no task root');
      const summarizer = new Summarizer({
        store,
        provider: liveProvider(),
        leafModel: MODEL,
        rootModel: MODEL,
        trace,
        blobs,
        costMeter: meter,
      });
      const outcomes = await summarizer.summarizeTree(root.id);

      // A contract violation surfaces as a failed outcome after one retry, so
      // this is the assertion the whole test is for: it fails loudly, naming
      // the field the live model would not produce.
      expect(outcomes.filter((outcome) => outcome.status === 'failed').map((o) => o.error?.message)).toEqual([]);

      // §8's content contract, on real output. Every field present (never
      // omitted, never null) — that is what makes relevance detectable from a
      // summary alone, and it is §9's unknown-unknowns mitigation.
      const tracePaths = new Set([PRICING]);
      const metaFields = ['files', 'symbols', 'tests', 'artifacts', 'open_questions', 'decisions', 'node_ids'] as const;
      for (const node of [root, ...store.children(root.id)]) {
        const summary = store.currentSummary(node.id);
        expect(summary, `no summary for ${node.title}`).not.toBeNull();
        if (summary === null) continue;
        expect(summary.text.length).toBeGreaterThan(20);
        for (const field of metaFields) {
          expect(Array.isArray(summary.meta[field]), `${node.title}.meta.${field} must be an array`).toBe(true);
        }
        // Spans are tree-sitter's (D9), so every path must be one the trace
        // actually touched — a live model inventing `src/utils.ts` here would
        // make every rehydration pointer in the system untrustworthy.
        for (const file of summary.meta.files) {
          expect(tracePaths.has(file.path), `hallucinated path ${file.path}`).toBe(true);
          expect(file.end_line).toBeGreaterThanOrEqual(file.start_line);
        }
        // The branch names itself as a fetch target, so a reader of the summary
        // can act on it without a search first.
        expect(summary.meta.node_ids).toContain(node.id);
      }

      // The implementation branch carries the real span, and it is the one
      // tree-sitter wrote — not one the model composed.
      const implementation = store.byKind('phase').find((node) => node.phase_type === 'implementation');
      if (implementation === undefined) throw new Error('no implementation phase');
      const implFiles = store.currentSummary(implementation.id)?.meta.files;
      expect(implFiles).toEqual(store.descendants(implementation.id).flatMap((node) => node.meta_json.spans ?? []));
      expect(implFiles?.length).toBeGreaterThan(0);

      // Resumption, same shape as the offline test: a fresh session reads the
      // flex buffer's summary blocks (closed phases with their §8 pointers), finds
      // the file and its fetch target there, and pulls the current content back
      // with one narrowed call.
      const src = await buildFlexSource({ store, trace, blobs }, { system: systemContract() });
      const prompt = assembleFlex(src.head, src.units, new HeuristicTokenizer(), { window: 1_000_000, anchor: 0 });
      const zoneB = prompt.blocks
        .filter((block) => block.zone === 'flex')
        .map((block) => block.text)
        .filter((text) => text.includes('fetchable nodes:'));
      const pricingBlock = [...zoneB].reverse().find((block) => /^files:.*src\/pricing\.ts/m.test(block));
      expect(pricingBlock, 'no Zone B block lists the edited file').toBeDefined();
      const branchId = /fetchable nodes: ([^,\n]+)/.exec(pricingBlock ?? '')?.[1];
      expect(branchId, 'no fetch target in the Zone B block').toBeDefined();

      const ctx: ToolContext = { config, handle, retriever: new TreeRetriever({ store, blobs, trace }) };
      const calls: ToolName[] = [CONTEXT_FETCH];
      const fetched = await HANDLERS[CONTEXT_FETCH](ctx, { branch_id: branchId, depth: 'full', file: PRICING });
      expect(fetched.ok, fetched.ok ? '' : `${fetched.error.code}: ${fetched.error.message}`).toBe(true);
      if (fetched.ok) expect((fetched.data as ContextFetchData).text).toContain(FIX_MARKER);
      // M5's ceiling. One call here, because Zone B answered the rest.
      expect(calls.length).toBeLessThanOrEqual(3);

      // §16: the run stayed inside its cap, and it actually spent something —
      // a zero would mean the meter was never wired to the calls.
      const spent = meter.totalUsd();
      expect(spent).toBeGreaterThan(0);
      expect(spent).toBeLessThan(CAP_USD);
      // An unpriced model is charged the priciest tier, so the cap still holds
      // — but it means the id drifted away from the price table (§11).
      expect(meter.unpricedModels()).toEqual([]);
    } finally {
      handle.close();
    }
  }, 180_000);
});

describe.skipIf(enabled)('live suite guard', () => {
  it('skips without LIVE=1 and a key, so CI never needs a secret (§17)', () => {
    expect(enabled).toBe(false);
  });
});

import { describe, it, expect } from 'vitest';
import { HeuristicTokenizer } from '../src/tokens/index.js';
import { assembleFlex, toMessages, toCompletionRequest, type FlexUnit } from '../src/assemble/index.js';
import { assertPrefixStable } from '../src/cache/index.js';

const tok = new HeuristicTokenizer();
const words = (n: number): string => 'ok '.repeat(Math.max(1, n)).trim(); // ~n tokens

interface UnitOpts {
  nodeId?: string;
  fps?: string[];
  wrote?: boolean;
  ref?: number;
  dormancy?: number;
  rawTok?: number;
  sumTok?: number;
  noSummary?: boolean;
}
const unit = (order: number, o: UnitOpts = {}): FlexUnit => ({
  nodeId: o.nodeId ?? `n${order}`,
  order,
  fingerprints: new Set(o.fps ?? []),
  wrote: o.wrote ?? false,
  lastReferencedTurn: o.ref ?? order,
  dormancy: o.dormancy ?? 0,
  raw: `RAW${order} ${words(o.rawTok ?? 30)}`,
  summary: o.noSummary ? undefined : `SUM${order} ${words(o.sumTok ?? 30)}`,
});

const bigWindow = { window: 1_000_000 };

describe('assembleFlex — frozen head', () => {
  it('head is system + steering + all user prompts, in order, zone head', () => {
    const p = assembleFlex(
      { system: 'SYS', steering: 'STEER', userPrompts: ['p0', 'p1'] },
      [unit(0)],
      tok,
      bigWindow,
    );
    const head = p.blocks.filter((b) => b.zone === 'head').map((b) => b.id);
    expect(head).toEqual(['head:system', 'head:steering', 'head:user:0', 'head:user:1']);
    expect(p.system).toContain('SYS');
    expect(p.system).toContain('p1');
  });

  it('a cache breakpoint is emitted after the head', () => {
    const p = assembleFlex({ system: 'SYS', userPrompts: ['p0'] }, [unit(0)], tok, bigWindow);
    const lastHead = p.blocks.filter((b) => b.zone === 'head').at(-1)!;
    expect(lastHead.cacheBreakpointAfter).toBe(true);
    expect(p.cacheBreakpoints).toContain(lastHead.id);
  });
});

describe('assembleFlex — representation & order', () => {
  it('the last A units stay raw; older units fold to summary', () => {
    const units = [unit(0), unit(1), unit(2), unit(3), unit(4)];
    const p = assembleFlex({ system: 'S', userPrompts: [] }, units, tok, { ...bigWindow, anchor: 2 });
    const flex = p.blocks.filter((b) => b.zone === 'flex');
    // older three summarised, last two raw
    expect(flex.slice(0, 3).every((b) => b.text.startsWith('SUM'))).toBe(true);
    expect(flex.slice(3).every((b) => b.text.startsWith('RAW'))).toBe(true);
  });

  it('kept units are emitted in creation order (append-only, never re-mixed)', () => {
    const units = [unit(0), unit(1), unit(2)];
    const p = assembleFlex({ system: 'S', userPrompts: [] }, units, tok, bigWindow);
    const ids = p.blocks.filter((b) => b.zone === 'flex').map((b) => b.nodeId);
    expect(ids).toEqual(['n0', 'n1', 'n2']);
  });

  it('a secondary breakpoint lands after the stable (summary) run', () => {
    const units = [unit(0), unit(1), unit(2), unit(3)];
    const p = assembleFlex({ system: 'S', userPrompts: [] }, units, tok, { ...bigWindow, anchor: 1 });
    // stable run = n0,n1,n2 (summaries); n3 raw. breakpoint after n2.
    const bpIds = p.cacheBreakpoints;
    expect(bpIds).toContain('flex:n2');
    const stable = p.blocks.find((b) => b.id === 'flex:n2')!;
    expect(stable.cacheBreakpointAfter).toBe(true);
  });
});

describe('assembleFlex — eviction to the floor', () => {
  it('over the floor, evicts the lowest-scoring (dormant, low-priority) unit; keeps anchors & high-priority', () => {
    const units = [
      unit(0, { nodeId: 'dormant', dormancy: 1, wrote: false }), // lowest score → evict
      unit(1, { nodeId: 'wrote', dormancy: 0, wrote: true }), // priority boost → keep
      unit(2, { nodeId: 'mid', dormancy: 0, wrote: false }), // keep
      unit(3, { nodeId: 'anchor', dormancy: 1, wrote: false }), // anchor: kept despite dormancy
    ];
    // window 200, floor 0.5 -> 100; each unit ~31 tokens; anchor=1.
    const p = assembleFlex({ system: 'S', userPrompts: [] }, units, tok, {
      window: 200,
      softTargetFrac: 0.5,
      anchor: 1,
    });
    const kept = p.blocks.filter((b) => b.zone === 'flex').map((b) => b.nodeId);
    expect(kept).toContain('anchor'); // anchor survives despite dormancy=1
    expect(kept).toContain('wrote');
    expect(kept).not.toContain('dormant'); // the lowest-scoring unit is evicted
    expect(p.budgets.evicted).toContain('dormant');
  });

  it('below the floor, keeps everything', () => {
    const units = [unit(0, { dormancy: 1 }), unit(1), unit(2)];
    const p = assembleFlex({ system: 'S', userPrompts: [] }, units, tok, bigWindow);
    expect(p.blocks.filter((b) => b.zone === 'flex')).toHaveLength(3);
    expect(p.budgets.evicted).toEqual([]);
  });
});

describe('assembleFlex — cache stability', () => {
  it('the head prefix is byte-stable when a new unit is appended', () => {
    const head = { system: 'SYS', userPrompts: ['p0'] };
    const before = assembleFlex(head, [unit(0), unit(1)], tok, bigWindow);
    const after = assembleFlex(head, [unit(0), unit(1), unit(2)], tok, bigWindow);
    // adding a flex unit must not disturb the frozen head prefix
    expect(() => assertPrefixStable(before, after, { throughZone: 'head' })).not.toThrow();
  });

  it('the head grows only at its end when a user prompt is appended', () => {
    const before = assembleFlex({ system: 'SYS', userPrompts: ['p0'] }, [unit(0)], tok, bigWindow);
    const after = assembleFlex({ system: 'SYS', userPrompts: ['p0', 'p1'] }, [unit(0)], tok, bigWindow);
    // append-only head: p0 stays put, p1 lands after it — the prefix only grew.
    expect(() => assertPrefixStable(before, after, { throughZone: 'head' })).not.toThrow();
    const headIds = after.blocks.filter((b) => b.zone === 'head').map((b) => b.id);
    expect(headIds).toEqual(['head:system', 'head:user:0', 'head:user:1']);
  });
});

describe('assembleFlex — stable-run cache invariant (through the secondary breakpoint)', () => {
  const head = { system: 'SYS', userPrompts: ['p0'] };
  // Blocks up to and including the secondary (flex) breakpoint — the cached stable prefix.
  const cachedPrefix = (p: ReturnType<typeof assembleFlex>) => {
    const bpId = p.cacheBreakpoints.at(-1)!;
    const idx = p.blocks.findIndex((b) => b.id === bpId);
    return p.blocks.slice(0, idx + 1);
  };
  const assertStable = (before: ReturnType<typeof assembleFlex>, after: ReturnType<typeof assembleFlex>) => {
    for (const b of cachedPrefix(before)) {
      const a = after.blocks.find((x) => x.id === b.id);
      expect(a, `block ${b.id} still present`).toBeDefined();
      expect(a!.text, `block ${b.id} byte-stable`).toBe(b.text);
    }
  };

  it('places the breakpoint after the LEADING contiguous summary run, not after a summary trailing a raw hole', () => {
    // unit 2 has no summary yet (async latch pending); 3,4,5 do; 6 is the raw anchor.
    const units = [unit(0), unit(1), unit(2, { noSummary: true }), unit(3), unit(4), unit(5), unit(6)];
    const p = assembleFlex(head, units, tok, { ...bigWindow, anchor: 1 });
    expect(p.cacheBreakpoints).toContain('flex:n1'); // after the leading run n0,n1
    expect(p.cacheBreakpoints).not.toContain('flex:n5'); // a summary behind the raw hole is NOT the breakpoint
  });

  it('a late summary latch on an old unit does not rewrite the cached stable prefix', () => {
    const mk = (latched: boolean) =>
      assembleFlex(
        head,
        [unit(0), unit(1), unit(2, latched ? {} : { noSummary: true }), unit(3), unit(4), unit(5), unit(6)],
        tok,
        { ...bigWindow, anchor: 1 },
      );
    assertStable(mk(false), mk(true)); // unit 2 raw → its summary latches: prefix must stay byte-stable
  });

  it('appending a new unit leaves the cached stable prefix byte-identical', () => {
    const before = assembleFlex(head, [unit(0), unit(1), unit(2), unit(3)], tok, { ...bigWindow, anchor: 1 });
    const after = assembleFlex(head, [unit(0), unit(1), unit(2), unit(3), unit(4)], tok, { ...bigWindow, anchor: 1 });
    assertStable(before, after);
  });
});

describe('toMessages / toCompletionRequest — provider projection', () => {
  const head = { system: 'SYS', steering: 'STEER', userPrompts: ['p0'] };
  const p = assembleFlex(head, [unit(0), unit(1), unit(2), unit(3)], tok, { ...bigWindow, anchor: 1 });

  it('the head ships as system, never as a message; flex + tail ship as user messages', () => {
    expect(p.system).toContain('SYS');
    const msgs = toMessages(p);
    expect(msgs.every((m) => m.role === 'user')).toBe(true);
    // No head content leaks into the messages.
    expect(msgs.every((m) => !m.content.includes('SYS'))).toBe(true);
    // The flex units are present.
    expect(msgs.some((m) => m.content.includes('SUM0') || m.content.includes('RAW3'))).toBe(true);
  });

  it('splits the flex zone at its secondary breakpoint: a cached message then the rest', () => {
    const msgs = toMessages(p);
    // n0,n1,n2 summaries (stable) with a breakpoint after n2; n3 raw anchor after it.
    const cached = msgs.find((m) => m.cacheBreakpoint === true);
    expect(cached).toBeDefined();
    expect(cached!.content).toContain('SUM2');
    expect(cached!.content).not.toContain('RAW3'); // the volatile anchor is in the second message
  });

  it('toCompletionRequest carries the head breakpoint as systemCacheBreakpoint and passes knobs through', () => {
    const req = toCompletionRequest(p, 'test-model', { maxTokens: 100, temperature: 0, json: true });
    expect(req.model).toBe('test-model');
    expect(req.system).toContain('STEER');
    expect(req.systemCacheBreakpoint).toBe(true); // head ends at a breakpoint
    expect(req.maxTokens).toBe(100);
    expect(req.json).toBe(true);
    expect(req.messages.length).toBeGreaterThan(0);
  });
});

