1	/**
2	 * Flex-buffer assembler (spec stage 2) — frozen head + creation-order flex buffer.
3	 *
4	 * Provenance: `flex-append-sticky` beat the shipped Zone A/B/C layout on cache
5	 * economics (~14% cheaper effective input cost; `flex-remix`, which re-picks the
6	 * mix each turn, is cache-death). SETTLED on cache economics (offline);
7	 * task-quality parity vs zones is an owed live check.
8	 * `reports/metrics/assembler-flex-buffer/report.md`.
9	 *
10	 * Layout (prefix order):
11	 *   head   system + steering + ALL user prompts, append-only, frozen → cached
12	 *   ── cache breakpoint after head ──
13	 *   flex   the units in CREATION ORDER: older closed units as summaries (the
14	 *          "stable head"), the recency anchor + active phase raw (the "volatile
15	 *          tail"). Evicted to a soft-target floor by the D-EV score.
16	 *   ── secondary breakpoint after the stable (summary) run ──
17	 *   tail   retrieved results, appended after the buffer so the prefix is untouched
18	 *
19	 * The buffer only appends and evicts in place; it never re-mixes (re-ordering the
20	 * prefix is cache-death). Dormancy comes from the classifier (stage 1); this stage
21	 * consumes it and never computes embeddings itself.
22	 *
23	 * NOT YET IMPLEMENTED (phased — `reports/session-handoff.md`): the reduce-on-overflow
24	 * router and the per-unit budget `b` (spec §"Reduce-on-overflow"). Eviction to the soft
25	 * floor is implemented; the overflow VALVE for an individual oversized raw unit is not.
26	 * A raw unit larger than `b` — including the recency anchor, which is never evicted — is
27	 * not yet chunked/summarized, so a single oversized raw unit can still exceed the floor
28	 * and the window.
29	 *
30	 * `toMessages` / `toCompletionRequest` project an assembled prompt to a provider
31	 * request: the head ships as `system` (its cache breakpoint as a request flag), and
32	 * the flex + tail blocks ship as messages, split at the secondary breakpoint.
33	 */
34	import type {
35	  AssembledPrompt,
36	  BudgetReport,
37	  ChatMessage,
38	  CompletionRequest,
39	  NodeId,
40	  PromptBlock,
41	  Tokenizer,
42	  ToolSchema,
43	  Zone,
44	} from '../contracts/index.js';
45	import {
46	  planEviction,
47	  DEFAULT_EVICTION_WEIGHTS,
48	  type EvictionCandidate,
49	  type EvictionWeights,
50	} from './eviction.js';
51	
52	/**
53	 * Soft-target floor `f`, as a fraction of the window: the buffer is evicted down
54	 * to this and never below it. Spec range 25–50%; the midpoint is the default.
55	 * PROVISIONAL — `f` is untested on a genuinely overflowing session
56	 * (`reports/session-handoff.md`, backlog item 7).
57	 */
58	export const DEFAULT_SOFT_TARGET_FRAC = 0.375;
59	
60	/**
61	 * Recency anchor `A`: the last A units are kept raw and never evicted.
62	 * PROVISIONAL — introduced as a read-loop guard, never swept.
63	 */
64	export const DEFAULT_ANCHOR = 4;
65	
66	/** Priority-decay half-life in turns (spec left the law open; exponential, ≈ A). PROVISIONAL. */
67	export const DEFAULT_PRIORITY_HALFLIFE = DEFAULT_ANCHOR;
68	
69	export type Representation = 'raw' | 'summary';
70	
71	/** One unit the assembler places. `dormancy` is the classifier's output (stage 1). */
72	export interface FlexUnit {
73	  nodeId: NodeId;
74	  /** Creation-order index; higher = newer. Units are supplied in ascending order. */
75	  order: number;
76	  fingerprints: ReadonlySet<string>;
77	  /** The phase wrote a file or was fetched → priority boost. */
78	  wrote: boolean;
79	  /** Turn index of the unit's last reference (for reference-recency + priority decay). */
80	  lastReferencedTurn: number;
81	  /** Continuous topic-shift dormancy from the classifier, higher = more dormant. */
82	  dormancy: number;
83	  /** The unit's full raw text (kept for the anchor / active phase). */
84	  raw: string;
85	  /** The unit's summary text, when it has been latched (older units fold to this). */
86	  summary?: string;
87	}
88	
89	/** The frozen head: never evicted, append-only. */
90	export interface FlexHead {
91	  system: string;
92	  steering?: string;
93	  /** All user prompts, in order — append-only so user intent is never evicted. */
94	  userPrompts: readonly string[];
95	}
96	
97	export interface FlexAssembleOptions {
98	  /** Host context window in tokens. Required for eviction (the floor is a fraction of it). */
99	  window: number;
100	  softTargetFrac?: number;
101	  anchor?: number;
102	  weights?: EvictionWeights;
103	  /** Current turn index, for priority decay + reference-recency. Defaults to max unit order. */
104	  currentTurn?: number;
105	  /** Retrieved results to append after the buffer (untouched prefix). */
106	  tail?: readonly { id: string; text: string }[];
107	  priorityHalfLife?: number;
108	}
109	
110	function sumTokens(blocks: readonly PromptBlock[]): number {
111	  return blocks.reduce((s, b) => s + b.tokens, 0);
112	}
113	
114	/** Number of other units sharing at least one fingerprint (recurrence). */
115	function coOccurrence(units: readonly FlexUnit[], i: number): number {
116	  const fp = units[i]!.fingerprints;
117	  let n = 0;
118	  for (let j = 0; j < units.length; j += 1) {
119	    if (j === i) continue;
120	    for (const f of fp) {
121	      if (units[j]!.fingerprints.has(f)) {
122	        n += 1;
123	        break;
124	      }
125	    }
126	  }
127	  return n;
128	}
129	
130	/**
131	 * Assemble the flex prompt. Units MUST be supplied in creation order. Older units
132	 * fold to their summary (if present); the last `anchor` units + any that lack a
133	 * summary stay raw. Eviction removes the lowest-scoring non-anchor units until the
134	 * buffer fits the soft-target floor `f`.
135	 */
136	export function assembleFlex(
137	  head: FlexHead,
138	  units: readonly FlexUnit[],
139	  tokenizer: Tokenizer,
140	  options: FlexAssembleOptions,
141	): AssembledPrompt {
142	  const window = options.window;
143	  if (!Number.isFinite(window) || window <= 0) {
144	    throw new RangeError('window must be a finite positive number of tokens');
145	  }
146	  const anchor = options.anchor ?? DEFAULT_ANCHOR;
147	  const softFrac = options.softTargetFrac ?? DEFAULT_SOFT_TARGET_FRAC;
148	  const weights = options.weights ?? DEFAULT_EVICTION_WEIGHTS;
149	  const halfLife = options.priorityHalfLife ?? DEFAULT_PRIORITY_HALFLIFE;
150	  const currentTurn = options.currentTurn ?? (units.length > 0 ? units[units.length - 1]!.order : 0);
151	  if (!Number.isFinite(softFrac) || softFrac < 0 || softFrac > 1) {
152	    throw new RangeError('softTargetFrac must be in [0, 1]');
153	  }
154	  if (!Number.isInteger(anchor) || anchor < 0) throw new RangeError('anchor must be a non-negative integer');
155	  if (!Number.isFinite(halfLife) || halfLife <= 0) throw new RangeError('priorityHalfLife must be > 0');
156	  // The buffer's cache discipline and anchor/eviction logic depend on creation order.
157	  for (let i = 1; i < units.length; i += 1) {
158	    if (units[i]!.order < units[i - 1]!.order) {
159	      throw new RangeError('units must be supplied in creation order (non-decreasing order)');
160	    }
161	  }
162	
163	  const block = (zone: PromptBlock['zone'], id: string, text: string, nodeId?: NodeId): PromptBlock => {
164	    const b: PromptBlock = { zone, id, text, tokens: tokenizer.count(text) };
165	    if (nodeId !== undefined) b.nodeId = nodeId;
166	    return b;
167	  };
168	
169	  // ── frozen head: system + steering + all user prompts, append-only ──────────
170	  const headBlocks: PromptBlock[] = [block('head', 'head:system', head.system)];
171	  if (head.steering !== undefined && head.steering !== '') {
172	    headBlocks.push(block('head', 'head:steering', head.steering));
173	  }
174	  head.userPrompts.forEach((p, i) => headBlocks.push(block('head', `head:user:${i}`, p)));
175	
176	  // ── representation: the last `anchor` units raw; older units fold to summary ─
177	  const n = units.length;
178	  const anchorFrom = Math.max(0, n - anchor);
179	  const repr = (i: number): Representation =>
180	    i >= anchorFrom || units[i]!.summary === undefined ? 'raw' : 'summary';
181	  const unitText = (i: number): string =>
182	    repr(i) === 'summary' ? units[i]!.summary! : units[i]!.raw;
183	  const unitTokens = (i: number): number => tokenizer.count(unitText(i));
184	
185	  // ── eviction: score every non-anchor unit; keep down to the floor `f` ───────
186	  const candidates: EvictionCandidate[] = units.map((u, i) => {
187	    const decay = Math.pow(0.5, Math.max(0, currentTurn - u.lastReferencedTurn) / halfLife);
188	    return {
189	      index: i,
190	      tokens: unitTokens(i),
191	      anchor: i >= anchorFrom,
192	      signals: {
193	        priority: ((u.wrote ? 2 : 0) + coOccurrence(units, i)) * decay,
194	        recency: u.order,
195	        refRecency: -(currentTurn - u.lastReferencedTurn),
196	        dormancy: u.dormancy,
197	      },
198	    };
199	  });
200	  const floor = Math.max(0, softFrac * window);
201	  const plan = planEviction(candidates, floor, weights);
202	  const keptIndices = new Set(plan.keep);
203	
204	  // ── flex blocks, CREATION ORDER, kept units only (append-only, never remixed) ─
205	  // The stable run is the LEADING CONTIGUOUS run of summary blocks; the secondary
206	  // breakpoint falls after it. A raw block — an anchor OR an old unit whose summary
207	  // has not latched yet (summarization is async) — CLOSES the stable run, so a later
208	  // raw→summary latch can never rewrite a block inside the cached prefix. Placing the
209	  // breakpoint after the last summary *anywhere* would trap such a raw hole before it.
210	  const flexBlocks: PromptBlock[] = [];
211	  let lastStableId: string | null = null;
212	  let stableRunOpen = true;
213	  for (let i = 0; i < n; i += 1) {
214	    if (!keptIndices.has(i)) continue;
215	    const u = units[i]!;
216	    const isSummary = repr(i) === 'summary';
217	    const b = block('flex', `flex:${u.nodeId}`, unitText(i), u.nodeId);
218	    flexBlocks.push(b);
219	    if (stableRunOpen && isSummary) lastStableId = b.id;
220	    else if (!isSummary) stableRunOpen = false;
221	  }
222	
223	  // ── tail: retrieved results, appended after the buffer ──────────────────────
224	  const tailEntries = options.tail ?? [];
225	  const tailBlocks = tailEntries.map((e) => block('tail', `tail:${e.id}`, e.text));
226	
227	  // ── breakpoints: after the head, and after the stable (summary) run ─────────
228	  const cacheBreakpoints: string[] = [];
229	  const lastHead = headBlocks.at(-1);
230	  if (lastHead !== undefined) {
231	    lastHead.cacheBreakpointAfter = true;
232	    cacheBreakpoints.push(lastHead.id);
233	  }
234	  if (lastStableId !== null) {
235	    const stable = flexBlocks.find((b) => b.id === lastStableId)!;
236	    stable.cacheBreakpointAfter = true;
237	    cacheBreakpoints.push(stable.id);
238	  }
239	
240	  const blocks = [...headBlocks, ...flexBlocks, ...tailBlocks];
241	  const headTokens = sumTokens(headBlocks);
242	  const flexTokens = sumTokens(flexBlocks);
243	  const tailTokens = sumTokens(tailBlocks);
244	  const total = headTokens + flexTokens + tailTokens;
245	
246	  const budgets: BudgetReport = {
247	    head: headTokens,
248	    flex: flexTokens,
249	    tail: tailTokens,
250	    total,
251	    overBudget: [],
252	    evicted: plan.evict.map((i) => units[i]!.nodeId),
253	    window,
254	    windowRemaining: window - total,
255	    // The prompt itself exceeds the window; reply room is reported via replyAllowance.
256	    overWindow: total > window,
257	    replyAllowance: Math.max(0, window - total),
258	    evictedFromTail: [],
259	  };
260	
261	  return {
262	    system: headBlocks.map((b) => b.text).join('\n\n'),
263	    blocks,
264	    budgets,
265	    cacheBreakpoints,
266	  };
267	}
268	
269	// ── provider projection ──────────────────────────────────────────────────────
270	
271	function isMarked(prompt: AssembledPrompt, block: PromptBlock): boolean {
272	  return block.cacheBreakpointAfter === true || prompt.cacheBreakpoints.includes(block.id);
273	}
274	
275	/** Does `zone` end at a cache breakpoint? */
276	function zoneEndsAtBreakpoint(prompt: AssembledPrompt, zone: Zone): boolean {
277	  const last = prompt.blocks.filter((b) => b.zone === zone).at(-1);
278	  return last !== undefined && isMarked(prompt, last);
279	}
280	
281	/**
282	 * Split a zone's blocks at its LAST marked block, so a breakpoint planted inside a
283	 * zone (the flex buffer's secondary breakpoint after the stable summary run) still
284	 * lands on a message boundary: everything through the marked block is one cacheable
285	 * message, the remainder is a second, uncached message.
286	 */
287	function splitAtLastMark(
288	  prompt: AssembledPrompt,
289	  blocks: readonly PromptBlock[],
290	): { cached: readonly PromptBlock[]; rest: readonly PromptBlock[] } {
291	  let cut = -1;
292	  for (let i = 0; i < blocks.length; i += 1) if (isMarked(prompt, blocks[i]!)) cut = i;
293	  if (cut === -1) return { cached: [], rest: blocks };
294	  return { cached: blocks.slice(0, cut + 1), rest: blocks.slice(cut + 1) };
295	}
296	
297	/**
298	 * Provider-facing projection: the head ships as `AssembledPrompt.system` (its
299	 * cache breakpoint is the system/messages boundary — carried by
300	 * `toCompletionRequest`, not here), and the `flex` and `tail` blocks ship as user
301	 * messages, one per zone, splitting a zone at its internal breakpoint.
302	 */
303	export function toMessages(prompt: AssembledPrompt): ChatMessage[] {
304	  const messages: ChatMessage[] = [];
305	  for (const zone of ['flex', 'tail'] as const) {
306	    const blocks = prompt.blocks.filter((b) => b.zone === zone);
307	    if (blocks.length === 0) continue;
308	    const { cached, rest } = splitAtLastMark(prompt, blocks);
309	    if (cached.length > 0) {
310	      messages.push({ role: 'user', content: cached.map((b) => b.text).join('\n\n'), cacheBreakpoint: true });
311	    }
312	    if (rest.length > 0) {
313	      messages.push({ role: 'user', content: rest.map((b) => b.text).join('\n\n') });
314	    }
315	  }
316	  return messages;
317	}
318	
319	/** Per-call knobs that are not the assembler's business (§11). */
320	export interface CompletionRequestOptions {
321	  maxTokens?: number;
322	  temperature?: number;
323	  /** Tool schemas as the provider's native tool list, not as prompt text. */
324	  tools?: readonly ToolSchema[];
325	  json?: boolean;
326	}
327	
328	/**
329	 * The whole prompt as one provider request — the frozen head as `system`, the
330	 * flex + tail blocks as messages, and both cache breakpoints attached (the head's
331	 * as `systemCacheBreakpoint`, the buffer's on its message).
332	 */
333	export function toCompletionRequest(
334	  prompt: AssembledPrompt,
335	  model: string,
336	  options: CompletionRequestOptions = {},
337	): CompletionRequest {
338	  const request: CompletionRequest = { model, system: prompt.system, messages: toMessages(prompt) };
339	  if (prompt.system !== '' && zoneEndsAtBreakpoint(prompt, 'head')) {
340	    request.systemCacheBreakpoint = true;
341	  }
342	  if (options.maxTokens !== undefined) request.maxTokens = options.maxTokens;
343	  if (options.temperature !== undefined) request.temperature = options.temperature;
344	  if (options.tools !== undefined) request.tools = options.tools;
345	  if (options.json !== undefined) request.json = options.json;
346	  return request;
347	}
348

