1	/**
2	 * §10 block text rendering + the one degradation primitive Zone C needs.
3	 *
4	 * Everything here is a pure function of its arguments (plus L2 reads, which are
5	 * write-once). That matters for D5: a block's text must be reproducible from the
6	 * same L1 row + L2 blobs on every turn, or the cached prefix moves for reasons
7	 * nobody can see.
8	 */
9	import type {
10	  BlobStore,
11	  NodeLink,
12	  NodeSummary,
13	  SymbolSpan,
14	  Tokenizer,
15	  TraceEvent,
16	  TreeNode,
17	} from '../contracts/index.js';
18	
19	function spanLabel(span: SymbolSpan): string {
20	  const parts = [`${span.path}:${span.start_line}-${span.end_line}`];
21	  if (span.symbol !== undefined) parts.push(`(${span.symbol})`);
22	  if (span.degraded === true) parts.push('[line-span only]');
23	  return parts.join(' ');
24	}
25	
26	/**
27	 * D18: no rendered meta list prints more than LIST_MAX_VALUES entries. The root
28	 * block's decisions/open-questions/fetchable-nodes are merges over EVERY child,
29	 * so an uncapped list re-introduces the ~50-tok/branch growth that capping the
30	 * root's headline list (D17) removed. Prompt lossy, L1 lossless — the full list
31	 * stays in the stored SummaryMeta and is reachable by context_fetch.
32	 */
33	const LIST_MAX_VALUES = 40;
34	
35	function listLine(label: string, values: readonly string[]): string | null {
36	  if (values.length === 0) return null;
37	  const shown = values.slice(0, LIST_MAX_VALUES);
38	  const more = values.length - shown.length;
39	  return `${label}: ${shown.join(', ')}${more > 0 ? ` (+${more} more)` : ''}`;
40	}
41	
42	/**
43	 * A Zone B summary block. The §8 rehydration pointers (files, symbols, tests,
44	 * artifacts, open questions, covered node ids) are rendered, not just the prose:
45	 * they are what lets the model notice it needs `context_fetch` at all (§9).
46	 */
47	export function renderSummaryBlock(node: TreeNode, summary: NodeSummary, isRoot: boolean): string {
48	  // No seq range here, deliberately: `span_end_seq` grows on every append to
49	  // the newest branch, and a volatile bit in a Zone B heading re-writes the
50	  // whole B segment each turn (the assembler's own "no per-block volatile
51	  // bits" rule — measured live as a ~2k cacheWrite every turn with cacheRead
52	  // pinned at Zone A). Seq coordinates stay reachable via `fetchable nodes`
53	  // and Zone C's active header, both outside the cached prefix.
54	  const heading = isRoot
55	    ? `# Task: ${node.title}`
56	    : `## Branch: ${node.title}${node.phase_type === null ? '' : ` [${node.phase_type}]`} (${node.status})`;
57	
58	  const lines: (string | null)[] = [
59	    heading,
60	    summary.text.trim(),
61	    listLine('files', summary.meta.files.map(spanLabel)),
62	    listLine('symbols', summary.meta.symbols),
63	    listLine(
64	      'tests',
65	      summary.meta.tests.map((t) => `${t.name}=${t.status}`),
66	    ),
67	    listLine(
68	      'artifacts',
69	      summary.meta.artifacts.map((a) => `${a.kind} ${a.ref}`),
70	    ),
71	    listLine('decisions', summary.meta.decisions),
72	    listLine('open questions', summary.meta.open_questions),
73	    listLine('fetchable nodes', summary.meta.node_ids),
74	  ];
75	  return lines.filter((line): line is string => line !== null && line !== '').join('\n');
76	}
77	
78	/**
79	 * D10 lateral links, rendered as their own block so that adding a link changes a
80	 * block id (`B:links:<node>:<count>`) instead of silently mutating the summary
81	 * block's text under a stable id — §17's cache assertions key on ids.
82	 */
83	export function renderLinksBlock(node: TreeNode, links: readonly NodeLink[]): string {
84	  const rendered = links.map((link) => `${link.kind} -> ${link.to_id}`);
85	  return `links from "${node.title}": ${rendered.join(', ')}`;
86	}
87	
88	/**
89	 * One L0 event as raw flex-buffer detail. L1 holds coordinates only (§6), so the
90	 * payload is always a blob read; a missing blob throws out of `blobs.get*`
91	 * rather than yielding a plausible-looking empty block.
92	 */
93	/**
94	 * Max rendered args bytes when a post-state blob is also present (v5.9b).
95	 *
96	 * Exported because the SAME rule has to hold wherever an event is rendered.
97	 * It did not: `retrieve/detail.ts` rendered `context_fetch` results with
98	 * uncapped args, so a write's content appeared twice — once JSON-escaped in the
99	 * args and once raw in the post-state — in exactly the payload the model reads
100	 * back. Measured on the frozen store: 6 of 754 events carry a byte-identical
101	 * duplicate that way, and it is a material part of why one branch tokenizes
102	 * larger than the window it is read into. One rule, one constant, both callers.
103	 */
104	export const ARGS_CAP_WITH_BLOB = 512;
105	
106	export function renderEvent(event: TraceEvent, blobs: BlobStore): string {
107	  switch (event.type) {
108	    case 'user_message':
109	      return `### user (seq ${event.seq})\n${blobs.getText(event.blob)}`;
110	    case 'assistant_message':
111	      return `### assistant (seq ${event.seq})\n${blobs.getText(event.blob)}`;
112	    case 'tool_call': {
113	      const target = event.path === undefined ? '' : ` ${event.path}`;
114	      const lines = [`### tool_call ${event.tool}${target} (seq ${event.seq})`];
115	      // v5.9b: when a post-state blob exists, args render CAPPED — a
116	      // write_file's args carry the whole file a second time, and that
117	      // duplicate rode through every cache write (1.25x) and read (0.1x/turn)
118	      // of the zone. Dropping args entirely went too far (measured: sw-1
119	      // turns 13 → 25 — an edit_file's args are the model's only record of
120	      // WHAT it changed; the post-state alone forces re-verification). The
121	      // cap keeps intent visible and kills the kilobyte-scale duplication,
122	      // one rule, no tool special-casing.
123	      if (event.args_blob !== undefined) {
124	        const args = blobs.getText(event.args_blob);
125	        lines.push(
126	          event.blob !== undefined && args.length > ARGS_CAP_WITH_BLOB
127	            ? `args: ${args.slice(0, safeCut(args, ARGS_CAP_WITH_BLOB))}${elision(args.length - safeCut(args, ARGS_CAP_WITH_BLOB))}`
128	            : `args: ${args}`,
129	        );
130	      }
131	      if (event.blob !== undefined) lines.push(blobs.getText(event.blob));
132	      return lines.join('\n');
133	    }
134	    case 'tool_result': {
135	      const flags = [
136	        event.error === undefined ? null : `error: ${event.error}`,
137	        event.truncated === true ? 'truncated by host' : null,
138	      ].filter((f): f is string => f !== null);
139	      const suffix = flags.length === 0 ? '' : ` [${flags.join('; ')}]`;
140	      const head = `### tool_result for seq ${event.call_seq} (seq ${event.seq})${suffix}`;
141	      return event.output_blob === undefined ? head : `${head}\n${blobs.getText(event.output_blob)}`;
142	    }
143	    case 'segment_boundary':
144	      return `### phase boundary ${event.from ?? 'none'} -> ${event.to} (seq ${event.seq})`;
145	    case 'manual_annotation':
146	      return `### annotation (seq ${event.seq})\n${blobs.getText(event.blob)}`;
147	  }
148	}
149	
150	/** A tail block — `context_fetch` / `context_search` / `context_peek` output. */
151	export function renderTailBlock(id: string, text: string, ephemeral: boolean): string {
152	  return `## retrieved: ${id}${ephemeral ? ' (dropped at the next phase boundary)' : ''}\n${text}`;
153	}
154	
155	const BARE_ELISION = '...';
156	
157	export function elision(dropped: number): string {
158	  return `\n...[${dropped} chars elided - call \`context_fetch\` for the full detail]`;
159	}
160	
161	/** Never split a surrogate pair — a lone half is not valid text to send. */
162	export function safeCut(text: string, at: number): number {
163	  const clamped = Math.max(0, Math.min(at, text.length));
164	  if (clamped <= 0 || clamped >= text.length) return clamped;
165	  const code = text.charCodeAt(clamped - 1);
166	  return code >= 0xd800 && code <= 0xdbff ? clamped - 1 : clamped;
167	}
168	
169	/**
170	 * Shrinks `text` to at most `maxTokens` under `tokenizer`, keeping the head and
171	 * saying loudly how much went missing. Truncation is deliberately visible in the
172	 * text: §10 rule 4's Zone C overflow is supposed to push the model toward a
173	 * narrow `context_fetch`, which it cannot do if the loss is invisible.
174	 */
175	export function truncateToTokens(text: string, maxTokens: number, tokenizer: Tokenizer): string {
176	  if (tokenizer.count(text) <= maxTokens) return text;
177	  // The marker's own cost is reserved against the longest form it can take
178	  // (the full length as the elided count), so the result never exceeds maxTokens.
179	  const bodyBudget = maxTokens - tokenizer.count(elision(text.length));
180	  if (bodyBudget <= 0) {
181	    // A cap this small drops the block in all but name. The `<= maxTokens`
182	    // guarantee is what makes Zone C's water-filling cap actually hold, so the
183	    // marker degrades to the cheapest thing that still says content was here.
184	    return tokenizer.count(BARE_ELISION) <= maxTokens ? BARE_ELISION : '';
185	  }
186	
187	  let lo = 0;
188	  let hi = text.length;
189	  while (lo < hi) {
190	    const mid = Math.ceil((lo + hi) / 2);
191	    if (tokenizer.count(text.slice(0, safeCut(text, mid))) <= bodyBudget) lo = mid;
192	    else hi = mid - 1;
193	  }
194	  const cut = safeCut(text, lo);
195	  return text.slice(0, cut) + elision(text.length - cut);
