/**
 * BM25 lexical ranker over the chunk corpus (spec stage 3). Replaces the
 * tested-and-lost IDF term-overlap ranker (`lexical.ts`): BM25 beat plain
 * IDF-beam directionally (`reports/metrics/rung-0e-retrievers/report-isolation.md`).
 * Standard Okapi BM25 with a non-negative idf form (`ln(1 + (N−df+0.5)/(df+0.5))`),
 * so a term in most documents never contributes a negative score. This is NOT
 * BM25+ (there is no δ lower-bound term).
 */
export const BM25_K1 = 1.2;
export const BM25_B = 0.75;

/** Lowercase alphanumeric tokens of length ≥ 2. */
export function tokenize(text: string): string[] {
  return (text.toLowerCase().match(/[a-z0-9]+/g) ?? []).filter((t) => t.length >= 2);
}

interface BM25Doc {
  id: string;
  tf: Map<string, number>;
  len: number;
}

export interface Scored {
  id: string;
  score: number;
}

export class BM25 {
  private readonly docs: BM25Doc[] = [];
  private readonly df = new Map<string, number>();
  private readonly avgdl: number;

  constructor(
    corpus: readonly { id: string; text: string }[],
    private readonly k1: number = BM25_K1,
    private readonly b: number = BM25_B,
  ) {
    if (!Number.isFinite(k1) || k1 < 0) throw new RangeError('BM25 k1 must be finite and ≥ 0');
    if (!Number.isFinite(b) || b < 0 || b > 1) throw new RangeError('BM25 b must be in [0, 1]');
    let totalLen = 0;
    for (const { id, text } of corpus) {
      const tokens = tokenize(text);
      const tf = new Map<string, number>();
      for (const t of tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
      for (const t of tf.keys()) this.df.set(t, (this.df.get(t) ?? 0) + 1);
      this.docs.push({ id, tf, len: tokens.length });
      totalLen += tokens.length;
    }
    this.avgdl = this.docs.length > 0 ? totalLen / this.docs.length : 0;
  }

  private idf(term: string): number {
    const df = this.df.get(term) ?? 0;
    const n = this.docs.length;
    return Math.log(1 + (n - df + 0.5) / (df + 0.5));
  }

  /** Ranked docs with score > 0, highest first. */
  search(query: string): Scored[] {
    const qTokens = [...new Set(tokenize(query))];
    const avgdl = this.avgdl || 1;
    const scored: Scored[] = [];
    for (const d of this.docs) {
      let score = 0;
      for (const t of qTokens) {
        const f = d.tf.get(t);
        if (f === undefined) continue;
        const idf = this.idf(t);
        score += (idf * (f * (this.k1 + 1))) / (f + this.k1 * (1 - this.b + (this.b * d.len) / avgdl));
      }
      if (score > 0) scored.push({ id: d.id, score });
    }
    return scored.sort((a, b) => b.score - a.score);
  }
}

/**
 * Reciprocal Rank Fusion (spec stage 3) — the SETTLED ensemble combinator.
 *
 * Provenance: plain RRF over a shared, overlapping-coverage corpus beat
 * best-single retriever, a feature router, and margin-gated fusion, both offline
 * and live (`reports/metrics/rung-0e-retrievers/`, `rung-2-retriever-live/`).
 * RRF is rank-based (scale-free): it never puts disjoint retrievers' scores on
 * one scale; overlapping coverage fuses, and a single-coverage query routes to
 * the sole coverer.
 *
 * `rrf(u) = Σ_r 1/(RRF_K + rank_r(u))`, rank 1-based.
 *
 * PROVISIONAL: `RRF_K = 60` is the literature default, never swept on this corpus.
 */
export const DEFAULT_RRF_K = 60;

import type { Scored } from './bm25.js';

/**
 * Fuse ranked id-lists into one ranking. Each input is a list of ids in rank
 * order (best first). Ids may appear in any subset of the inputs. Returns fused
 * ids with their RRF scores, highest first.
 */
export function reciprocalRankFusion(
  rankings: readonly (readonly string[])[],
  k: number = DEFAULT_RRF_K,
): Scored[] {
  if (!Number.isFinite(k) || k < 0) throw new RangeError('RRF k must be finite and ≥ 0');
  const scores = new Map<string, number>();
  for (const ranking of rankings) {
    ranking.forEach((id, i) => {
      scores.set(id, (scores.get(id) ?? 0) + 1 / (k + i + 1)); // rank = i + 1
    });
  }
  return [...scores.entries()]
    .map(([id, score]) => ({ id, score }))
    .sort((a, b) => b.score - a.score);
}

