184	    if (nodeId !== undefined) b.nodeId = nodeId;
185	    return b;
186	  };
187	
188	  // ── frozen head: system + steering + all user prompts, append-only ──────────
189	  const headBlocks: PromptBlock[] = [block('head', 'head:system', head.system)];
190	  if (head.steering !== undefined && head.steering !== '') {
191	    headBlocks.push(block('head', 'head:steering', head.steering));
192	  }
