/** A visible gap marker between kept spans — pushes the model toward `context_fetch` (§10 rule 4). */
function gapMarker(droppedChunks: number): string {
  const n = droppedChunks;
  return `\n…[${n} span${n === 1 ? '' : 's'} elided — call \`context_fetch\` for the full detail]…\n`;
}

