    // pointing at the chunk that holds the detail.
    const withVec = reduceChunk({ raw: buried }, ctx({ query: 'zzz', vectorRanking: [] }));
    // The important guarantee: supplying a vectorRanking never throws and still
    // returns a budget-fitting excerpt.
    expect(tok.count(withVec)).toBeLessThanOrEqual(40);
  });

