  it('folds to the latched summary, clamped to budget', () => {
    const out = reduceSummarize({ raw: buried, summary: 'A short gist of the change.' }, ctx());
    expect(out).toContain('gist');
    expect(tok.count(out)).toBeLessThanOrEqual(40);
