1	/**
2	 * §9 `context_fetch` — expansion. `depth: 'summary'` is an L1 read;
3	 * `depth: 'full'` (the default, R9) replays the branch's L0 span through L2;
4	 * `depth: 'index'` (R10) lists that span's events instead of reading them.
5	 * `file` narrows any depth to the file node(s) keyed by one path (§10 rule 4);
6	 * `from`/`to` (R10) additionally narrows a `'full'`/`'index'` read to an
7	 * inclusive L0 `seq` range.
8	 */
9	import { z } from 'zod';
10	import type { NodeId, NodeKind, PhaseType, SeqSpan, SummaryMeta } from '@context-tree/core';
11	import { failFrom, ok, parseArgs, requireNode } from '../result.js';
12	import { recordRetrieval } from '../observe.js';
13	import type { ToolContext, ToolOutcome } from '../types.js';
14	
15	export const CONTEXT_FETCH = 'context_fetch';
16	
17	/**
18	 * Zone A content (D5): permanent in every prompt, so every token is paid for
19	 * forever. It states the TRIGGER, not the mechanics — with no fine-tuning
20	 * anywhere (D7), this text plus the system contract is the entire policy.
21	 *
22	 * The read-before-edit rule (§9 contract rule 1) is stated here rather than
23	 * left to the system prompt because a host may install the tools without the
24	 * contract, and the tool list is the one thing it cannot install without.
25	 */
26	export const CONTEXT_FETCH_DESCRIPTION =
27	  'Return a recorded branch of this task: the full events under it (the default), an index of those ' +
28	  'events, or its summary. Reach for it BEFORE EDITING any file whose current content is not already ' +
29	  'in your context — your memory of a file predates whatever a later branch did to it — and whenever a ' +
30	  'summary names a file, test or ticket you are about to touch, or whenever your answer must reproduce ' +
31	  "a number, an identifier, or someone's exact words: a summary can tell you something happened, never " +
32	  "what it said. A branch too large to read whole: call with `depth: 'index'` first to see its events, " +
33	  'then narrow with `from`/`to`. The result lands in the transcript tail only: it never mutates the ' +
34	  'stored tree and never invalidates the cached prompt prefix.';
35	
36	const shape = {
37	  branch_id: z.string().min(1).describe('Node id of the branch to read, as returned by context_search.'),
38	  depth: z
39	    .enum(['summary', 'index', 'full'])
40	    .optional()
41	    .describe(
42	      "'full' (default) replays every recorded event under the branch; 'index' lists those events " +
43	        "(seq, type, tool, path, bytes) without reading their content; 'summary' returns the branch's " +
44	        'stored paraphrase, which cannot contain a literal the paraphrase dropped.',
45	    ),
46	  file: z
47	    .string()
48	    .min(1)
49	    .optional()
50	    .describe('Repo-relative path: read only the file node(s) under this branch keyed by it.'),
51	  from: z
52	    .number()
53	    .int()
54	    .optional()
55	    .describe("Inclusive L0 event number to start at (depth 'full'/'index' only). Clamped to the branch's own span."),
56	  to: z
57	    .number()
58	    .int()
59	    .optional()
60	    .describe("Inclusive L0 event number to end at (depth 'full'/'index' only). Clamped to the branch's own span."),
61	};
62	
63	export const contextFetchSchema = z.object(shape);
64	export const contextFetchInputShape = shape;
65	
66	export interface ContextFetchData {
67	  branch_id: NodeId;
68	  kind: NodeKind;
69	  title: string;
70	  phase_type: PhaseType | null;
71	  depth: 'summary' | 'index' | 'full';
72	  file: string | null;
73	  /** 0 when §8 has not summarized this branch yet, or several nodes were merged. */
74	  summary_version: number;
75	  /** The §8 rehydration pointers — read these first to judge what else to fetch. */
76	  meta: SummaryMeta | null;
77	  /** Nodes this result actually covers; each is a valid `context_peek` target. */
78	  nodes: NodeId[];
79	  /** L0 ranges read. Empty at depth `summary`, which touches L1 only. */
80	  spans: SeqSpan[];
81	  events: number;
82	  text: string;
83	}
84	
85	export async function contextFetch(ctx: ToolContext, input: unknown): Promise<ToolOutcome<ContextFetchData>> {
86	  const parsed = parseArgs(contextFetchSchema, input);
87	  if (!parsed.ok) return parsed;
88	  const args = parsed.data;
89	
90	  const branch = requireNode(ctx, 'branch_id', args.branch_id);
91	  if (!branch.ok) return branch;
92	
93	  try {
94	    const fetched = ctx.retriever.fetchBranch(args.branch_id, {
95	      depth: args.depth ?? 'full',
96	      file: args.file,
97	      from: args.from,
98	      to: args.to,
99	    });
100	    const data: ContextFetchData = {
101	      branch_id: fetched.nodeId,
102	      kind: fetched.kind,
103	      title: fetched.title,
104	      phase_type: fetched.phaseType,
105	      depth: fetched.depth,
106	      file: fetched.file ?? null,
107	      summary_version: fetched.summaryVersion,
108	      meta: fetched.meta,
109	      nodes: fetched.nodes,
110	      spans: fetched.spans,
111	      events: fetched.events,
112	      text: fetched.text,
113	    };
114	    recordRetrieval(ctx, CONTEXT_FETCH, args, data);
115	    return ok(data);
116	  } catch (error) {
117	    return failFrom(error);
118	  }
119	}
