1	/**
2	 * §17's provider cache simulator — "asserting exactly which prefix ranges
3	 * survive each event type".
4	 *
5	 * The model, and why it is shaped this way:
6	 *
7	 * Provider caches are keyed on a PREFIX and can only be cut at an emitted
8	 * breakpoint (§10 rule 5 puts exactly two of them in, at the Zone A/B and B/C
9	 * boundaries). So a prompt is a list of SEGMENTS, split at the breakpoints the
10	 * provider actually honours, plus a trailing remainder after the last one that
11	 * is never cacheable. A read takes the LONGEST cached prefix that still matches
12	 * byte-for-byte; everything after that boundary up to the last breakpoint is a
13	 * cache WRITE, and the trailing remainder is fresh input every single turn.
14	 *
15	 * The consequence this exists to measure: one changed byte in Zone B invalidates
16	 * Zone B and everything after it, but NOT Zone A. That asymmetry is the entire
17	 * reason §10 rule 1 forbids relevance-ordering Zone B, and it is invisible to
18	 * every other kind of test — the model sees the same text either way.
19	 *
20	 * `matchPolicy` (default `'automatic-prefix'`) decides HOW a submission's
21	 * prefix is checked against cache history — see the two modes documented on
22	 * `ProviderCacheSimulatorOptions`. Iteration 2 of the tuning loop
23	 * (tuning iteration 2, experiment 4) diagnosed the
24	 * original algorithm — matching only the immediately previous submission's
25	 * exact breakpoint positions — as unable to credit a read for a breakpoint
26	 * that moves forward by one block every turn, because that exact position
27	 * never recurs. That produced a false "+23% more expensive" verdict on the
28	 * Zone C 3rd breakpoint that a live, already-published measurement directly
29	 * contradicts (`reports/metrics/tree-vs-transcript.md:155`: cacheRead
30	 * climbing 4,788→23,794, cacheWrite staying delta-sized at ~1.2k, −18% cost
31	 * per turn) — and which Anthropic's own documented behaviour explains: a
32	 * single trailing breakpoint is matched against the LONGEST previously
33	 * cached prefix, not against one specific remembered position. `'exact-last-
34	 * position'` is the original algorithm, preserved byte-for-byte and still
35	 * reachable for anything that wants the more conservative model.
36	 *
37	 * Two remaining simplifications, both still conservative in the sense the
38	 * original comment claimed:
39	 *  - `'automatic-prefix'` tracks one running "longest known cached prefix",
40	 *    refreshed to this submission's own furthest cacheable position every
41	 *    turn. A real provider's cache persists under a TTL independent of what
42	 *    any one request's breakpoints reference, so a submission that (unlike
43	 *    every submission actually observed in this codebase) *drops* a
44	 *    previously-placed breakpoint would, in this model, lose credit for
45	 *    everything past its new, shorter reach a turn earlier than a real TTL
46	 *    would — under-crediting, not over-crediting, in that edge case.
47	 *  - the tokenizer is INJECTED and its id is stamped on every outcome (§17's
48	 *    "deterministic tokenizer"), and block tokens are re-counted from `text`
49	 *    rather than trusting `PromptBlock.tokens`. The harness's numbers must be a
50	 *    function of the bytes it was handed, so that swapping the tokenizer shows
51	 *    up as a deliberate diff in recorded ranges instead of silently shifting
52	 *    every one of them.
53	 */
54	import type { AssembledPrompt, Tokenizer, Zone } from '../contracts/index.js';
55	import { CacheAssertionError } from './prefix.js';
56	
57	/**
58	 * Per-provider cache behaviour (§18 risk row 4: "cache behavior differs per
59	 * provider" -> "per-provider cache-simulator tests; provider-neutral layout +
60	 * provider-specific cache markers"). Only the two knobs that actually change
61	 * which ranges survive are modelled.
62	 */
63	export interface CacheProviderProfile {
64	  id: string;
65	  /**
66	   * Breakpoints honoured per request; the rest are ignored and their blocks fold
67	   * into the following segment.
68	   */
69	  maxBreakpoints: number;
70	  /**
71	   * A breakpoint whose whole preceding prefix is smaller than this is not cached
72	   * at all — the provider's minimum cacheable prefix.
73	   */
74	  minCacheableTokens: number;
75	}
76	
77	/**
78	 * The harness default: every emitted breakpoint is honoured and there is no
79	 * minimum. Deliberately provider-neutral, because §17's assertions are about
80	 * the LAYOUT surviving, and a provider minimum would make every small fixture
81	 * report "nothing cached" and assert nothing.
82	 */
83	export const EXACT_PREFIX_PROFILE: CacheProviderProfile = {
84	  id: 'exact-prefix',
85	  maxBreakpoints: Number.POSITIVE_INFINITY,
86	  minCacheableTokens: 0,
87	};
88	
89	/**
90	 * Anthropic prompt caching: at most 4 `cache_control` breakpoints, and a
91	 * 1024-token minimum cacheable prefix on Sonnet/Opus-class models (Haiku's is
92	 * higher — construct a profile with that minimum to model it).
93	 */
94	export const ANTHROPIC_PROFILE: CacheProviderProfile = {
95	  id: 'anthropic',
96	  maxBreakpoints: 4,
97	  minCacheableTokens: 1024,
98	};
99	
100	/** One breakpoint-delimited run of blocks. */
101	export interface CacheSegment {
102	  /** Position in the prompt's segment list. */
103	  index: number;
104	  /** Zones this segment spans, in order — `"A"`, `"B"`, `"C+tail"`. */
105	  label: string;
106	  zones: Zone[];
107	  blockIds: string[];
108	  tokens: number;
109	  /** Exclusive block index this segment ends at — the provider's cache key. */
110	  endBlockIndex: number;
111	  /** Id of the block whose breakpoint closes it; null for the trailing remainder. */
112	  breakpointBlockId: string | null;
113	  /** False only for the trailing remainder: nothing after the last breakpoint is cached. */
114	  cacheable: boolean;
115	}
116	
117	export interface SegmentOutcome extends CacheSegment {
118	  /** Read from cache on this submission rather than re-sent. */
119	  reused: boolean;
120	}
121	
122	export interface CacheOutcome {
123	  /** 1-based ordinal within the session. */
124	  submission: number;
125	  /** Recorded so a tokenizer swap is a visible diff, never a silent shift (§17). */
126	  tokenizerId: string;
127	  profileId: string;
128	  cacheRead: number;
129	  cacheWrite: number;
130	  /** Input tokens neither read from nor written to cache — the uncacheable tail. */
131	  fresh: number;
132	  /** `cacheRead + cacheWrite + fresh`, and the sum of every block's tokens. */
133	  total: number;
134	  /** Blocks matching the previous submission position-for-position, by id AND text. */
135	  commonPrefixBlocks: number;
136	  /**
137	   * Tokens in that byte-identical block prefix — what a provider with a
138	   * breakpoint at every block could have reused. Always >= `cacheRead`; the gap
139	   * is the price of §10 rule 5 allowing only two breakpoints, and it is the
140	   * number that documents the honest cost of a mid-Zone-B rewrite (D3/D4).
141	   */
142	  commonPrefixTokens: number;
143	  /** Block where divergence began; null on the first submission or an exact repeat. */
144	  divergedAtBlockId: string | null;
145	  divergedInZone: Zone | null;
146	  segments: SegmentOutcome[];
147	  /** Labels of the segments that survived intact. */
148	  survivingSegments: string[];
149	}
150	
151	/** A block reduced to what the cache actually keys on. */
152	interface MeasuredBlock {
153	  id: string;
154	  zone: Zone;
155	  text: string;
156	  tokens: number;
157	  breakpointAfter: boolean;
158	}
159	
160	interface Submission {
161	  blocks: MeasuredBlock[];
162	  segments: CacheSegment[];
163	}
164	
165	/**
166	 * How a submission's prefix is checked against cache history.
167	 *
168	 *  - `'automatic-prefix'` (the default): matches against the LONGEST prefix
169	 *    ever cached, refreshed each turn to this submission's own furthest
170	 *    cacheable position. This is what lets a single breakpoint that moves
171	 *    forward by one block every turn still earn a read for everything before
172	 *    the new block — exactly the "climbing reads, delta-sized writes" shape
173	 *    `reports/metrics/tree-vs-transcript.md:155` measured live, and what
174	 *    Anthropic's own documented behaviour describes for a trailing
175	 *    breakpoint. A dropped breakpoint (the regression `cache.test.ts` guards
176	 *    against) still shows up as zero reads, because a submission with no
177	 *    cacheable segment cannot extend or read the cached prefix at all.
178	 *  - `'exact-last-position'`: the original algorithm, preserved byte-for-byte.
179	 *    It only credits a read when the CURRENT submission's breakpoint lands at
180	 *    the exact block position one of the PREVIOUS submission's breakpoints
181	 *    also landed at. This under-credits any breakpoint that advances by less
182	 *    than a whole previously-seen segment each turn (§1 of
183	 *    tuning iteration 2, experiment 4) — kept as an
184	 *    explicit opt-in for anything that wants that stricter, more
185	 *    pessimistic model rather than as the default.
186	 */
187	export type CacheMatchPolicy = 'automatic-prefix' | 'exact-last-position';
188	
189	export interface ProviderCacheSimulatorOptions {
190	  tokenizer: Tokenizer;
191	  /** Defaults to `EXACT_PREFIX_PROFILE`. */
192	  profile?: CacheProviderProfile;
193	  /** Defaults to `'automatic-prefix'`. See `CacheMatchPolicy`. */
194	  matchPolicy?: CacheMatchPolicy;
195	}
196	
197	export class ProviderCacheSimulator {
198	  private readonly tokenizer: Tokenizer;
199	  private readonly profile: CacheProviderProfile;
200	  private readonly matchPolicy: CacheMatchPolicy;
201	  private previous: Submission | null = null;
202	  /** `'automatic-prefix'` only: the longest prefix confirmed cached so far. */
203	  private cachedPrefix: MeasuredBlock[] = [];
204	  private readonly log: CacheOutcome[] = [];
205	
206	  constructor(options: ProviderCacheSimulatorOptions) {
207	    this.tokenizer = options.tokenizer;
208	    this.profile = options.profile ?? EXACT_PREFIX_PROFILE;
209	    this.matchPolicy = options.matchPolicy ?? 'automatic-prefix';
210	  }
211	
212	  /** Submits one assembled prompt and reports what the cache did with it. */
213	  submit(prompt: AssembledPrompt): CacheOutcome {
214	    const blocks = this.measure(prompt);
215	    const segments = this.segment(blocks);
216	    const previous = this.previous;
217	
218	    // This diagnostic (commonPrefixBlocks/commonPrefixTokens) is deliberately
219	    // scoped to the immediately previous submission only, regardless of
220	    // matchPolicy — it answers "how much of literally last turn's bytes
221	    // survived", the number the D3/D4 cascade tests key on, which is a
222	    // different question from "how much can the provider actually serve from
223	    // cache" below.
224	    let commonPrefixBlocks = 0;
225	    let commonPrefixTokens = 0;
226	    if (previous !== null) {
227	      while (commonPrefixBlocks < blocks.length && commonPrefixBlocks < previous.blocks.length) {
228	        const mine = blocks[commonPrefixBlocks];
229	        const theirs = previous.blocks[commonPrefixBlocks];
230	        if (mine === undefined || theirs === undefined) break;
231	        if (mine.id !== theirs.id || mine.text !== theirs.text) break;
232	        commonPrefixTokens += mine.tokens;
233	        commonPrefixBlocks += 1;
234	      }
235	    }
236	
237	    let outcomeSegments: SegmentOutcome[];
238	    let cacheRead = 0;
239	    let cacheWrite = 0;
240	    let fresh = 0;
241	
242	    if (this.matchPolicy === 'exact-last-position') {
243	      // Original algorithm, unchanged: a read hits the longest cached prefix
244	      // that still matches, so the boundary is the furthest segment end that
245	      // (a) the previous submission actually cached at that EXACT position and
246	      // (b) is still byte-identical. Requiring (a) at exact-position
247	      // granularity is what makes a breakpoint that moves every turn never
248	      // earn a read here — the documented limitation this policy exists to
249	      // preserve on request.
250	      const previouslyCached = new Set(
251	        (previous?.segments ?? []).filter((s) => s.cacheable).map((s) => s.endBlockIndex),
252	      );
253	      let readBoundary = 0;
254	      for (const segment of segments) {
255	        if (!segment.cacheable) continue;
256	        if (segment.endBlockIndex > commonPrefixBlocks) break;
257	        if (!previouslyCached.has(segment.endBlockIndex)) continue;
258	        readBoundary = segment.endBlockIndex;
259	      }
260	
261	      outcomeSegments = segments.map((segment) => ({
262	        ...segment,
263	        reused: segment.cacheable && segment.endBlockIndex <= readBoundary,
264	      }));
265	      for (const segment of outcomeSegments) {
266	        if (segment.reused) cacheRead += segment.tokens;
267	        else if (segment.cacheable) cacheWrite += segment.tokens;
268	        else fresh += segment.tokens;
269	      }
270	    } else {
271	      // 'automatic-prefix': match against the longest prefix ever cached,
272	      // not only the immediately previous submission's exact breakpoint
273	      // positions. Read credit is computed at BLOCK granularity — a segment
274	      // can be partially read and partially (re)written — because that
275	      // partial credit inside a single marked span is exactly the mechanism
276	      // that produces delta-sized writes under one moving breakpoint; a
277	      // whole-segment-or-nothing model cannot reproduce that shape no matter
278	      // how much history it is given.
279	      let commonWithCache = 0;
280	      while (commonWithCache < blocks.length && commonWithCache < this.cachedPrefix.length) {
281	        const mine = blocks[commonWithCache];
282	        const theirs = this.cachedPrefix[commonWithCache];
283	        if (mine === undefined || theirs === undefined) break;
284	        if (mine.id !== theirs.id || mine.text !== theirs.text) break;
285	        commonWithCache += 1;
286	      }
287	      const furthestCacheableEnd = segments.reduce(
288	        (max, s) => (s.cacheable ? Math.max(max, s.endBlockIndex) : max),
289	        0,
290	      );
291	      const readBoundary = Math.min(commonWithCache, furthestCacheableEnd);
292	
293	      outcomeSegments = segments.map((segment) => ({
294	        ...segment,
295	        reused: segment.cacheable && segment.endBlockIndex <= readBoundary,
296	      }));
297	      for (let i = 0; i < blocks.length; i += 1) {
298	        const block = blocks[i];
299	        if (block === undefined) continue;
300	        if (i < readBoundary) cacheRead += block.tokens;
301	        else if (i < furthestCacheableEnd) cacheWrite += block.tokens;
302	        else fresh += block.tokens;
303	      }
304	
305	      this.cachedPrefix = blocks.slice(0, furthestCacheableEnd);
306	    }
307	
308	    const divergence = this.divergence(blocks, previous, commonPrefixBlocks);
309	    const outcome: CacheOutcome = {
310	      submission: this.log.length + 1,
311	      tokenizerId: this.tokenizer.id,
312	      profileId: this.profile.id,
313	      cacheRead,
314	      cacheWrite,
315	      fresh,
316	      total: cacheRead + cacheWrite + fresh,
317	      commonPrefixBlocks,
318	      commonPrefixTokens,
319	      divergedAtBlockId: divergence?.id ?? null,
320	      divergedInZone: divergence?.zone ?? null,
321	      segments: outcomeSegments,
322	      survivingSegments: outcomeSegments.filter((s) => s.reused).map((s) => s.label),
323	    };
324	
325	    this.previous = { blocks, segments };
326	    this.log.push(outcome);
327	    return outcome;
328	  }
329	
330	  /** Every outcome so far, in submission order — `cacheReport`'s input. */
331	  outcomes(): readonly CacheOutcome[] {
332	    return this.log;
333	  }
334	
335	  private measure(prompt: AssembledPrompt): MeasuredBlock[] {
336	    const marked = new Set(prompt.cacheBreakpoints);
337	    return prompt.blocks.map((block) => ({
338	      id: block.id,
339	      zone: block.zone,
340	      text: block.text,
341	      tokens: this.tokenizer.count(block.text),
342	      // Either channel counts: the assembler sets the flag on the block and
343	      // lists the id, and a hand-built prompt in a test may set only one.
344	      breakpointAfter: block.cacheBreakpointAfter === true || marked.has(block.id),
345	    }));
346	  }
347	
348	  private segment(blocks: readonly MeasuredBlock[]): CacheSegment[] {
349	    const segments: CacheSegment[] = [];
350	    let start = 0;
351	    let prefixTokens = 0;
352	    let honoured = 0;
353	
354	    for (let i = 0; i < blocks.length; i += 1) {
355	      const block = blocks[i];
356	      if (block === undefined) continue;
357	      prefixTokens += block.tokens;
358	      if (!block.breakpointAfter) continue;
359	      if (honoured >= this.profile.maxBreakpoints) continue;
360	      if (prefixTokens < this.profile.minCacheableTokens) continue;
361	      honoured += 1;
362	      segments.push(makeSegment(segments.length, blocks.slice(start, i + 1), start, block.id, true));
363	      start = i + 1;
364	    }
365	    if (start < blocks.length) {
366	      segments.push(makeSegment(segments.length, blocks.slice(start), start, null, false));
367	    }
368	    return segments;
369	  }
370	
371	  /**
372	   * The block where this submission stopped matching the previous one. A block
373	   * present on only one side counts: a removal invalidates the suffix exactly as
374	   * a rewrite does.
375	   */
376	  private divergence(
377	    blocks: readonly MeasuredBlock[],
378	    previous: Submission | null,
379	    commonPrefixBlocks: number,
380	  ): { id: string; zone: Zone } | null {
381	    if (previous === null) return null;
382	    const mine = blocks[commonPrefixBlocks];
383	    if (mine !== undefined) return { id: mine.id, zone: mine.zone };
384	    const theirs = previous.blocks[commonPrefixBlocks];
385	    if (theirs !== undefined) return { id: theirs.id, zone: theirs.zone };
386	    return null;
387	  }
388	}
389	
390	function makeSegment(
391	  index: number,
392	  blocks: readonly MeasuredBlock[],
393	  startBlockIndex: number,
394	  breakpointBlockId: string | null,
395	  cacheable: boolean,
396	): CacheSegment {
397	  const zones: Zone[] = [];
398	  let tokens = 0;
399	  for (const block of blocks) {
400	    if (!zones.includes(block.zone)) zones.push(block.zone);
401	    tokens += block.tokens;
402	  }
403	  return {
404	    index,
405	    label: zones.join('+'),
406	    zones,
407	    blockIds: blocks.map((block) => block.id),
408	    tokens,
409	    endBlockIndex: startBlockIndex + blocks.length,
410	    breakpointBlockId,
411	    cacheable,
412	  };
413	}
414	
415	/**
416	 * §15's headline cost metric: "input tokens (cache-read vs cache-write split)"
417	 * across a whole session. The eval harness aggregates arms through this.
418	 */
419	export interface CacheSessionReport {
420	  tokenizerId: string;
421	  profileId: string;
422	  submissions: number;
423	  cacheRead: number;
424	  cacheWrite: number;
425	  fresh: number;
426	  total: number;
427	  /** `cacheRead / total` — 0 when nothing was submitted. */
428	  cacheReadRatio: number;
429	}
430	
431	export function cacheReport(outcomes: readonly CacheOutcome[]): CacheSessionReport {
432	  const first = outcomes[0];
433	  if (first === undefined) {
434	    throw new CacheAssertionError('cacheReport: no submissions to aggregate');
435	  }
436	
437	  const report: CacheSessionReport = {
438	    tokenizerId: first.tokenizerId,
439	    profileId: first.profileId,
440	    submissions: outcomes.length,
441	    cacheRead: 0,
442	    cacheWrite: 0,
443	    fresh: 0,
444	    total: 0,
445	    cacheReadRatio: 0,
446	  };
447	
448	  for (const outcome of outcomes) {
449	    // Mixing tokenizers or providers makes the aggregate meaningless, and a
450	    // meaningless cost split in a §15 results table is worse than a crash.
451	    if (outcome.tokenizerId !== report.tokenizerId) {
452	      throw new CacheAssertionError(
453	        `cacheReport: mixed tokenizers (${report.tokenizerId} vs ${outcome.tokenizerId}) — token ranges are not comparable`,
454	      );
455	    }
456	    if (outcome.profileId !== report.profileId) {
457	      throw new CacheAssertionError(
458	        `cacheReport: mixed provider profiles (${report.profileId} vs ${outcome.profileId}) — cache behaviour differs per provider (§18)`,
459	      );
460	    }
461	    report.cacheRead += outcome.cacheRead;
462	    report.cacheWrite += outcome.cacheWrite;
463	    report.fresh += outcome.fresh;
464	    report.total += outcome.total;
465	  }
466	
467	  if (report.total > 0) report.cacheReadRatio = report.cacheRead / report.total;
468	  return report;
469	}
