/** single-version: one block per file (latest text, in-place), + convo stream. */
function runSingleVersion(events, edited, placed) {
  const sim = new ProviderCacheSimulator({ tokenizer, profile: ANTHROPIC_PROFILE });
  const stream = [blk('task', 'flex', 'TASK')]; // ordered convo + file blocks (file blocks mutated in place)
  const fileBlock = new Map(); // file -> block object (shared, mutated)
  let n = 0;
  const touchFile = (file, text) => {
    let b = fileBlock.get(file);
    if (!b) { b = blk(`f:${file}`, edited.has(file) ? 'flex' : 'head', text); fileBlock.set(file, b); stream.push(b); }
    else b.text = text; // version swap: mutate in place -> invalidates from its position
  };
  for (const e of events) {
    if (e.t === 'assistant') {
      let blocks, bps;
      if (!placed) {
        blocks = [blk('sys', 'head', SYS), ...stream];
        bps = ['sys', blocks[blocks.length - 1].id];
      } else {
        // static head: system + reference files (never edited); volatile: convo + edit-target files.
        const refs = stream.filter((b) => b.id.startsWith('f:') && !edited.has(b.id.slice(2)));
        const rest = stream.filter((b) => !(b.id.startsWith('f:') && !edited.has(b.id.slice(2))));
        blocks = [blk('sys', 'head', SYS), ...refs, ...rest];
        bps = ['sys'];
        if (refs.length) bps.push(refs[refs.length - 1].id);
        if (rest.length) bps.push(rest[rest.length - 1].id);
        else bps.push(blocks[blocks.length - 1].id);
      }
      submit(sim, blocks, bps);
      stream.push(blk(`a${n++}`, 'flex', e.text));
    } else if (e.t === 'read') touchFile(e.file, e.text);
    else if (e.t === 'edit') {
