1	/**
2	 * ============================================================================
3	 * INTEGRATION (best-of-breed): the full middleware in one agent loop
4	 * ============================================================================
5	 * Only the validated good stuff, wired together (middleware.mjs):
6	 *   RETRIEVER  = ensemble RRF(BM25, vector/MiniLM) chunk-retrieve, router-gated
7	 *   CLASSIFIER = topic-shift dormancy z(lexical)+z(semantic) drift vs recent window
8	 *   ASSEMBLER  = D-EV priority eviction (priority-dominant + recency, relevance≈0),
9	 *                dormant-first ejection, recency anchor, reduce-on-overflow
10	 * vs TRUNCATE-TAIL (raw + recency). Realistic toolset (incl. run_bash), so the
11	 * model CAN self-retrieve — this asks whether the whole thing works in a realistic
12	 * agent, and where it breaks. Under the served model's window (8.2K if that model).
13	 *
14	 * RERUN: CT_LOCAL_MODEL=unsloth/Qwen3.8-Flash-Next-GGUF \
15	 *        node experiments/coding-harness/integration-full.mjs
16	 * ============================================================================
17	 */
18	import { execSync } from 'node:child_process';
19	import { writeFileSync } from 'node:fs';
20	import { join } from 'node:path';
21	import { runAgent, makeWorkspace, evictRecency, estTokens, MODEL } from './lib.mjs';
22	import { REDUCERS } from './reducers.mjs';
23	import { makeEmbedder, makeEnsembleReducer, makeAssembler } from './middleware.mjs';
24	import { writeResults, gitSha, nowISO } from '../rung-1-live-probe/lib.mjs';
25	
26	const BUDGET = 6800;
27	const ITEMS = [{ file: 'widget_catalog.md', name: 'Widget', price: 13 }, { file: 'gadget_catalog.md', name: 'Gadget', price: 27 },
28	  { file: 'gizmo_catalog.md', name: 'Gizmo', price: 41 }, { file: 'doohickey_catalog.md', name: 'Doohickey', price: 58 }];
29	const TOTAL = ITEMS.reduce((s, i) => s + i.price, 0);
30	
31	function seed(ws) {
32	  const secs = ['Overview', 'Specifications', 'Materials', 'Assembly', 'Warranty', 'Compliance', 'Shipping', 'Returns', 'Support', 'Maintenance'];
33	  const filler = (s, n) => (`The ${s} section of the ${n} catalog details conventions, procedures, and expectations at length. Integrators should review this and cross-reference parameters. `).repeat(15);
34	  for (const it of ITEMS) {
35	    const lines = [`# ${it.name} Catalog`, ''];
36	    for (const s of secs) { lines.push(`## ${s}`, filler(s, it.name)); if (s === 'Specifications') lines.push(`Pricing note: the ${it.name} unit price is ${it.price} dollars per unit.`); lines.push(''); }
37	    writeFileSync(join(ws, it.file), lines.join('\n'));
38	  }
39	}
40	const SYSTEM = 'You are an agent in a workspace. Use the tools to read files and run commands. Work step by step; when finished reply with a short message containing DONE and no tool call.';
41	const TASK = `Four catalogs are in the workspace: ${ITEMS.map((i) => i.file).join(', ')}. Read each and find its product unit price. Write ONLY the integer sum of the four prices to answer.txt, then reply DONE.`;
42	
43	async function runArm(config, embed) {
44	  const ws = makeWorkspace(); seed(ws);
45	  const track = { peak: 0, evictions: 0 };
46	  const reducer = config === 'full' ? makeEnsembleReducer(embed) : REDUCERS.none;
47	  const evict = config === 'full' ? makeAssembler(embed, BUDGET) : (m) => evictRecency(m, BUDGET);
48	  const hook = async (m) => { track.peak = Math.max(track.peak, estTokens(m)); if (await evict(m)) track.evictions++; };
49	  let err = null, r = null;
