/**
 * Context-eviction policies under test, extracted as a PURE, importable module so
 * they can be unit-tested without executing a sweep (`ab-window-sweep.mjs` runs a
 * live experiment on import, which is untestable by construction).
 *
 * Every policy mutates the `messages` array IN PLACE (that is the harness hook
 * contract in coding-harness/lib.mjs) and returns true iff it evicted anything.
 *
 * INVARIANT all policies must preserve: an assistant message carrying tool_calls
 * always travels with its following tool results, so eviction can never orphan a
 * tool result from its call (a malformed-request trap). `extractUnits` gives us
 * that grouping; every policy keeps or drops whole units.
 */
import { extractUnits, estTokens, evictRecency } from '../coding-harness/lib.mjs';

export const DEFAULT_ANCHOR = 4;

/** Deterministic PRNG (mulberry32) so the random control reruns identically. */
export function makeRng(seed = 0x9e3779b9) {
  let s = seed | 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Replace `messages` with pinned head + the kept units, in order, in place. */
export function rebuildLocal(messages, pinned, keptUnits) {
  const next = [...pinned, ...keptUnits.flatMap((u) => u.slice)];
  messages.length = 0;
  messages.push(...next);
}

/**
 * Per-unit IDLE in units: how long since this unit's fingerprints were last
 * referenced by a LATER unit. A unit never re-referenced has idle = distance to
 * the newest unit. This is the trivially-countable backward signal Tier 1
 * validated (idle predicts cold: precision 98%).
 */
export function idleOf(units) {
  const N = units.length;
  return units.map((u, i) => {
    let last = i;
    for (let j = N - 1; j > i; j--) {
      if ([...u.fp].some((f) => units[j].fp.has(f))) { last = j; break; }
    }
    return N - 1 - last;
  });
}

/** Indices of the recency anchor (the last `anchor` units), never evicted. */
export function anchorSet(n, anchor = DEFAULT_ANCHOR) {
  return new Set(Array.from({ length: Math.min(anchor, n) }, (_, k) => n - 1 - k));
}

/**
 * LRU-at-g*: drop any non-anchor unit whose idle exceeds `g` (the cache break-even
 * w/r, ~12.5 turns), then enforce the hard cap `W` with a recency backstop.
 */
export function evictIdleThenFit(messages, W, g, anchor = DEFAULT_ANCHOR) {
  const { pinned, units } = extractUnits(messages);
  const N = units.length;
  if (N === 0) return false;
  const idle = idleOf(units);
  const keepAnchor = anchorSet(N, anchor);
  const kept = units.filter((u, i) => keepAnchor.has(i) || idle[i] <= g);
  const droppedByIdle = kept.length !== N;
  if (droppedByIdle) rebuildLocal(messages, pinned, kept);
  const trimmed = evictRecency(messages, W); // hard cap backstop
  return droppedByIdle || trimmed;
}

/**
 * CONTROL: evict RANDOM non-anchor units until the prompt fits `W`. Ablates the
 * selection signal at matched volume — if recency/idle beat this, the signal is
 * doing the work rather than mere shrinkage.
 */
export function evictRandomToFit(messages, W, rng = makeRng(), anchor = DEFAULT_ANCHOR, reserve = 512) {
  const { pinned, units } = extractUnits(messages);
  const N = units.length;
  if (N === 0) return false;
  const avail = W - estTokens(pinned) - reserve;
  if (avail <= 0 || estTokens(units.flatMap((u) => u.slice)) <= avail) return false;
  const keepAnchor = anchorSet(N, anchor);
  const keepIdx = new Set(keepAnchor);
  let used = [...keepAnchor].reduce((s, i) => s + estTokens(units[i].slice), 0);
  const rest = units.map((_, i) => i).filter((i) => !keepAnchor.has(i));
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  for (const i of rest) { const t = estTokens(units[i].slice); if (used + t <= avail) { keepIdx.add(i); used += t; } }
  if (keepIdx.size === N) return false;
  rebuildLocal(messages, pinned, [...keepIdx].sort((a, b) => a - b).map((i) => units[i]));
  return true;
}

