/**
 * Unit tests for the context-eviction policies (node:test, stdlib — no deps).
 * Run: node --test experiments/context-dedup/policies.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { extractUnits, estTokens } from '../coding-harness/lib.mjs';
import { evictIdleThenFit, evictRandomToFit, idleOf, anchorSet, makeRng, rebuildLocal } from './policies.mjs';

const PINNED = [
  { role: 'system', content: 'SYSTEM' },
  { role: 'user', content: 'TASK' },
];
/** One unit = assistant(tool_calls) + its tool result. `path` drives the fingerprint. */
const unit = (path, body = 'x'.repeat(400)) => [
  { role: 'assistant', content: '', tool_calls: [{ id: `c_${path}`, function: { name: 'read_file', arguments: JSON.stringify({ path }) } }] },
  { role: 'tool', tool_call_id: `c_${path}`, content: body },
];
const build = (paths) => [...PINNED.map((m) => ({ ...m })), ...paths.flatMap((p) => unit(p))];
/** No tool result may appear without its assistant tool_call immediately before it. */
function assertNoOrphans(messages) {
  for (let i = 0; i < messages.length; i++) {
    if (messages[i].role !== 'tool') continue;
    let j = i - 1;
    while (j >= 0 && messages[j].role === 'tool') j--;
    assert.ok(j >= 0 && messages[j].role === 'assistant' && messages[j].tool_calls?.length,
      `orphaned tool result at index ${i}`);
  }
}

test('extractUnits groups an assistant tool_call with its tool result (no orphans)', () => {
  const m = build(['a.py', 'b.py', 'c.py']);
  const { pinned, units } = extractUnits(m);
  assert.equal(pinned.length, 2);
  assert.equal(units.length, 3);
  for (const u of units) assert.equal(u.slice.length, 2);
});

test('idleOf: a unit never re-referenced has idle = distance to newest', () => {
  const { units } = extractUnits(build(['a.py', 'b.py', 'c.py', 'd.py']));
  const idle = idleOf(units);
  assert.deepEqual(idle, [3, 2, 1, 0]); // oldest is 3 behind the newest
});

test('idleOf: re-referencing an old file RESETS its idle (reference-recency, not position)', () => {
  // a.py is read first, then again last → its idle must be 0 even though it is positionally oldest.
  const { units } = extractUnits(build(['a.py', 'b.py', 'c.py', 'a.py']));
  const idle = idleOf(units);
  assert.equal(idle[0], 0, 'first a.py is referenced again by the last unit → idle 0');
  assert.equal(idle[1], 2, 'b.py never re-referenced');
});

test('anchorSet protects exactly the last N units', () => {
  assert.deepEqual([...anchorSet(6, 4)].sort((a, b) => a - b), [2, 3, 4, 5]);
  assert.deepEqual([...anchorSet(2, 4)].sort((a, b) => a - b), [0, 1]); // fewer units than anchor
});

test('evictIdleThenFit drops units idle > g* but never the anchor', () => {
  const m = build(['a.py', 'b.py', 'c.py', 'd.py', 'e.py', 'f.py', 'g.py', 'h.py']);
  const before = extractUnits(m).units.length;
  const changed = evictIdleThenFit(m, 1e9, 2, 2); // g*=2, anchor=2, huge W so only the idle rule acts
  assert.equal(changed, true);
  const { units } = extractUnits(m);
  assert.ok(units.length < before, 'some units evicted');
  // survivors are the anchor (last 2) plus anything with idle <= 2 → the tail block
  assert.ok(units.length <= 4, `expected a small tail, got ${units.length}`);
  assertNoOrphans(m);
});

test('evictIdleThenFit KEEPS a positionally-old unit that was re-referenced (the discriminator)', () => {
  // a.py: read first AND re-read last → idle 0 → must survive even with a tiny g*.
  const m = build(['a.py', 'b.py', 'c.py', 'd.py', 'e.py', 'a.py']);
  evictIdleThenFit(m, 1e9, 1, 1); // g*=1, anchor=1 → only reference-recency can save the old a.py
  const kept = extractUnits(m).units.map((u) => [...u.files][0]);
  assert.ok(kept.includes('a.py'), 'old-but-re-referenced a.py must be retained');
  assert.ok(!kept.includes('c.py'), 'a genuinely cold middle unit should be gone');
  assertNoOrphans(m);
});

test('evictIdleThenFit enforces the hard cap W via the recency backstop', () => {
  const m = build(Array.from({ length: 12 }, (_, i) => `f${i}.py`));
  evictIdleThenFit(m, 1200, 99, 1); // g* huge (idle rule inert) → cap must still bind
  assert.ok(estTokens(m) <= 1200 + 600, `expected ~<=W, got ${estTokens(m)}`);
  assertNoOrphans(m);
});

test('evictIdleThenFit is a no-op when everything is hot and fits', () => {
  const m = build(['a.py', 'b.py']);
  const copy = JSON.stringify(m);
  const changed = evictIdleThenFit(m, 1e9, 99, 4);
  assert.equal(changed, false);
  assert.equal(JSON.stringify(m), copy, 'must not mutate when nothing is evicted');
});

test('evictRandomToFit fits the budget, keeps the anchor, and never orphans', () => {
  const m = build(Array.from({ length: 12 }, (_, i) => `f${i}.py`));
  const changed = evictRandomToFit(m, 1500, makeRng(42), 2);
  assert.equal(changed, true);
  assert.ok(estTokens(m) <= 1500, `over budget: ${estTokens(m)}`);
  const kept = extractUnits(m).units.map((u) => [...u.files][0]);
  assert.ok(kept.includes('f11.py') && kept.includes('f10.py'), 'anchor units retained');
  assertNoOrphans(m);
});

test('evictRandomToFit is deterministic for a given seed (rerunnable control)', () => {
  const run = () => { const m = build(Array.from({ length: 12 }, (_, i) => `f${i}.py`)); evictRandomToFit(m, 1500, makeRng(7), 2); return extractUnits(m).units.map((u) => [...u.files][0]); };
  assert.deepEqual(run(), run());
});

test('evictRandomToFit is a no-op when already under budget', () => {
  const m = build(['a.py']);
  assert.equal(evictRandomToFit(m, 1e9, makeRng(1), 4), false);
});

test('rebuildLocal preserves pinned head and unit order', () => {
  const m = build(['a.py', 'b.py', 'c.py']);
  const { pinned, units } = extractUnits(m);
  rebuildLocal(m, pinned, [units[0], units[2]]);
  assert.equal(m[0].content, 'SYSTEM');
  assert.equal(m[1].content, 'TASK');
