/**
 * A/B WINDOW-CAP SWEEP — one model, one substrate, sweep the artificial window.
 *
 * Design (why this is the right shape):
 *   - ONE model: Qwen3.8-27B (262K real window), so the provider never rejects a
 *     prompt. The only synthetic element is an artificial cap W enforced by the
 *     assembler each turn — which is exactly what a deployment window IS. Full
 *     tools are kept (no artificial tool removal), so this is ecological.
 *   - Sweep W from ample (task completes for every policy) down to tight (only a
 *     good policy survives). With full tools, self-heal turns truncation into extra
 *     RE-READS, so the metric is the (window × turns-to-complete) frontier, not a
 *     binary pass/fail. This finds the window+time budget in one sweep.
 *
 * Arms (one variable — the context policy that fits the cap W):
 *   uncapped     — no cap (W=∞ reference); establishes the task completes at all.
 *   truncate-tail— keep the most-recent units that fit W (the baseline harness default).
 *   random       — CONTROL: evict random non-anchor units to W (seeded).
 *   idle-gstar   — drop units idle > g* turns, then fit W by recency (the derived rule).
 *
 * The task is PLUGGABLE (see ./ab-tasks/*.mjs); pass its name in CT_TASK. A task
 * exports { name, system, task, seed(ws), grade(ws)->bool, allowedTools? }.
 *
 * LIVE. Rerun:
 *   set -a; . ./.env; set +a
 *   CT_LOCAL_MODEL=unsloth/Qwen3.8-27B-GGUF CT_WINDOWS=200000,32000,16000,8000,4000 \
 *     node experiments/context-dedup/ab-window-sweep.mjs
 */
import { execSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { runAgent, makeWorkspace, evictRecency, extractUnits, estTokens, MODEL } from '../coding-harness/lib.mjs';
import { writeResults, gitSha, nowISO } from '../rung-1-live-probe/lib.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const WINDOWS = (process.env.CT_WINDOWS || '200000,32000,16000,8000,4000').split(',').map(Number);
const GSTAR = +(process.env.CT_GSTAR || 12);
const MAX_TURNS = +(process.env.CT_MAX_TURNS || 40);
const ANCHOR = +(process.env.CT_ANCHOR || 4);
const ARMS = (process.env.CT_ARMS || 'uncapped,truncate-tail,random,idle-gstar').split(',');
const TASK_NAME = process.env.CT_TASK || 'rule-chain';

// ── seeded RNG for the random control ────────────────────────────────────────
let _seed = 0x9e3779b9;
const resetRng = () => { _seed = 0x9e3779b9; };
function rng() { _seed = (_seed + 0x6d2b79f5) | 0; let t = Math.imul(_seed ^ (_seed >>> 15), 1 | _seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function rebuildLocal(messages, pinned, kept) { const next = [...pinned, ...kept.flatMap((u) => u.slice)]; messages.length = 0; messages.push(...next); }

/** drop units idle > g* turns (by reference recency), then fit W by recency backstop. */
function evictIdleThenFit(messages, W, g) {
  const { pinned, units } = extractUnits(messages);
  const N = units.length;
  const lastRef = units.map((u, i) => { let last = i; for (let j = N - 1; j > i; j--) if ([...u.fp].some((f) => units[j].fp.has(f))) { last = j; break; } return last; });
  const anchor = new Set(Array.from({ length: Math.min(ANCHOR, N) }, (_, k) => N - 1 - k));
  let kept = units.filter((u, i) => anchor.has(i) || (N - 1 - lastRef[i]) <= g);
  const changed = kept.length !== N;
  rebuildLocal(messages, pinned, kept);
  const trimmed = evictRecency(messages, W); // hard cap backstop
  return changed || trimmed;
}
/** evict RANDOM non-anchor units until the prompt fits W (control). */
function evictRandomToFit(messages, W, reserve = 512) {
  const { pinned, units } = extractUnits(messages);
  const avail = W - estTokens(pinned) - reserve;
  if (avail <= 0 || estTokens(units.flatMap((u) => u.slice)) <= avail) return false;
  const N = units.length;
  const anchor = new Set(Array.from({ length: Math.min(ANCHOR, N) }, (_, k) => N - 1 - k));
  const keepIdx = new Set(anchor); let used = [...anchor].reduce((s, i) => s + estTokens(units[i].slice), 0);
  const rest = units.map((_, i) => i).filter((i) => !anchor.has(i));
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  for (const i of rest) { const t = estTokens(units[i].slice); if (used + t <= avail) { keepIdx.add(i); used += t; } }
  if (keepIdx.size === N) return false;
  rebuildLocal(messages, pinned, [...keepIdx].sort((a, b) => a - b).map((i) => units[i]));
  return true;
}
function evictorFor(arm, W) {
  if (arm === 'uncapped') return () => false;
  if (arm === 'truncate-tail') return (m) => evictRecency(m, W);
  if (arm === 'random') return (m) => evictRandomToFit(m, W);
  if (arm === 'idle-gstar') return (m) => evictIdleThenFit(m, W, GSTAR);
  throw new Error(`unknown arm ${arm}`);
}

async function runCell(task, arm, W) {
  if (arm === 'random') resetRng();
  const ws = makeWorkspace(); task.seed(ws);
  const track = { peak: 0, evictions: 0 };
  const evict = evictorFor(arm, W);
  const hook = async (m) => { track.peak = Math.max(track.peak, estTokens(m)); if (await evict(m)) track.evictions++; };
  let err = null, r = null;
  try { r = await runAgent({ system: task.system, task: task.task, ws, maxTurns: MAX_TURNS, think: false, hook, allowedTools: task.allowedTools ?? null }); }
  catch (e) { err = String(e.message || e).slice(0, 200); }
  let pass = false; try { pass = task.grade(ws); } catch {}
  const reads = r ? r.toolLog.filter((t) => t.name === 'read_file').length : 0;
  const distinct = r ? new Set(r.toolLog.filter((t) => t.name === 'read_file').map((t) => t.args?.path)).size : 0;
  return { arm, window: arm === 'uncapped' ? null : W, pass, turns: r?.turns ?? null, stop: r?.stop ?? 'error',
    evictions: track.evictions, peak_history_tokens: track.peak, reads, rereads: reads - distinct,
    total_prompt_tokens: r ? r.usage.reduce((s, u) => s + (u.prompt_tokens || 0), 0) : 0, error: err };
}

async function main() {
  const task = (await import(join(HERE, 'ab-tasks', `${TASK_NAME}.mjs`))).default;
  const cells = [];
  // uncapped once (window-independent), then each capped arm across the window sweep
  if (ARMS.includes('uncapped')) { console.error(`\n--- uncapped ---`); cells.push(await runCell(task, 'uncapped', Infinity)); }
  for (const W of WINDOWS) for (const arm of ARMS) {
    if (arm === 'uncapped') continue;
    console.error(`\n--- W=${W} ${arm} ---`);
    cells.push(await runCell(task, arm, W));
  }
  const out = {
    manifest: {
      run_id: `ab-window-sweep-${TASK_NAME}-${Date.now()}`, experiment: `context-dedup / A/B window-cap sweep (${TASK_NAME})`,
      model: MODEL, task: task.name, windows: WINDOWS, g_star: GSTAR, max_turns: MAX_TURNS, anchor: ANCHOR,
      commit: gitSha(), date: nowISO(),
      hypothesis: 'idle-gstar completes at a SMALLER window (and/or in fewer turns) than truncate-tail, and beats the random control — because it retains re-referenced-but-positionally-old units that truncate-tail evicts.',
      falsification: 'if idle-gstar does not complete at a smaller window than truncate-tail, nor in fewer turns at equal window, and does not beat random, the derived rule adds nothing over the baseline harness.',
      caveats: ['n=1 per cell, temp 0.', 'total_prompt_tokens is RAW (local server caching unknown).', 'FULL tools kept — self-heal makes truncation cost turns/re-reads, not hard failure; the frontier is (window × turns).'],
    }, cells,
  };
  const path = writeResults('context-dedup', `results-ab-${TASK_NAME}.json`, out);
  console.error(`\n=== A/B WINDOW SWEEP [${task.name}] model=${MODEL} g*=${GSTAR} ===  [pass|turns|evict|reads|rereads|peak|total]`);
  for (const c of cells) console.error(`  W=${String(c.window ?? '∞').padStart(7)} ${c.arm.padEnd(13)} ${c.pass ? 'PASS' : 'FAIL'}  turns=${c.turns}  evict=${c.evictions}  reads=${c.reads}  rereads=${c.rereads}  peak=${c.peak_history_tokens}  total=${c.total_prompt_tokens}  ${c.error ? 'ERR=' + c.error : ''}`);
  console.error(`  written: ${path}`);
}
main().catch((e) => { console.error('FATAL', e); process.exit(1); });

