10	 *
11	 * Charts are hand-built inline SVG: no CDN, renders offline from the repo.
12	 *
13	 * Rerun: node experiments/context-dedup/report-ab-combined.mjs
14	 */
15	import { readFileSync, writeFileSync, existsSync } from 'node:fs';
16	import { dirname, join } from 'node:path';
17	import { fileURLToPath } from 'node:url';
18	
19	const HERE = dirname(fileURLToPath(import.meta.url));
20	const OUT = join(HERE, '..', '..', 'reports', 'metrics', 'context-dedup');
21	const N3 = join(OUT, 'results-ab-longbuild-v2-n3.json');
22	const N10 = join(OUT, 'results-ab-longbuild-v2.json');
23	
24	const ARMS = ['truncate-tail', 'random', 'idle'];
25	const LABEL = { 'truncate-tail': 'truncate-tail (positional)', random: 'random (control)', idle: 'idle (reference recency)' };
26	const COLOR = { 'truncate-tail': '#6b7bd6', random: '#9aa0ad', idle: '#e4572e' };
27	
28	// ── stats ───────────────────────────────────────────────────────────────────
29	const logFact = (() => { const c = [0, 0]; return (n) => { for (let i = c.length; i <= n; i++) c[i] = c[i - 1] + Math.log(i); return c[n]; }; })();
30	const lchoose = (n, k) => (k < 0 || k > n ? -Infinity : logFact(n) - logFact(k) - logFact(n - k));
31	/** Two-tailed Fisher exact on [[a,b],[c,d]]. */
32	function fisher(a, b, c, d) {
33	  const n = a + b + c + d, r1 = a + b, c1 = a + c;
34	  const p = (x) => Math.exp(lchoose(r1, x) + lchoose(n - r1, c1 - x) - lchoose(n, c1));
35	  const obs = p(a);
36	  let tot = 0;
37	  for (let x = Math.max(0, c1 - (n - r1)); x <= Math.min(r1, c1); x++) { const q = p(x); if (q <= obs * (1 + 1e-9)) tot += q; }
38	  return Math.min(1, tot);
39	}
40	const med = (xs) => { const s = [...xs].sort((a, b) => a - b); return s.length ? (s.length % 2 ? s[(s.length - 1) / 2] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2) : 0; };
41	
42	// ── load ────────────────────────────────────────────────────────────────────
43	const load = (p) => (existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : null);
44	const b3 = load(N3);
45	let b10 = load(N10);
46	if (!b3) throw new Error(`missing ${N3}`);
47	// GUARD: the harness writes results only when a run COMPLETES, so while the n=10
48	// sweep is still running results-ab-longbuild-v2.json is still the n=3 file.
49	// Pooling it with itself would double-count the same runs and invent significance.
50	if (b10 && b3.manifest?.run_id === b10.manifest?.run_id) {
51	  console.error('[guard] n=10 file has the same run_id as n=3 (run not finished yet) — treating n=10 as ABSENT.');
52	  b10 = null;
53	} else if (b10 && (b10.manifest?.repeats ?? 0) <= (b3.manifest?.repeats ?? 0)) {
54	  console.error(`[guard] n=10 file reports repeats=${b10.manifest?.repeats} (<= n=3 batch) — treating as ABSENT.`);
55	  b10 = null;
56	}
57	const cellsOf = (b, arm, W) => (b?.cells ?? []).filter((c) => c.arm === arm && (W === 'inf' ? c.window === null : c.window === W));
58	const agg = (cs) => cs.length ? {
59	  n: cs.length, pass: cs.filter((c) => c.pass).length,
60	  passRate: cs.filter((c) => c.pass).length / cs.length,
61	  turns: med(cs.map((c) => c.turns ?? 0)), turnsMin: Math.min(...cs.map((c) => c.turns ?? 0)), turnsMax: Math.max(...cs.map((c) => c.turns ?? 0)),
62	  rereads: med(cs.map((c) => c.rereads)), rereadsMin: Math.min(...cs.map((c) => c.rereads)), rereadsMax: Math.max(...cs.map((c) => c.rereads)),
63	  evict: med(cs.map((c) => c.evictions)), peak: med(cs.map((c) => c.peak_history_tokens)),
