77	
78	const ft = (x, y) => (x && y ? fisher(x.pass, x.n - x.pass, y.pass, y.n - y.pass) : NaN);
79	const stats = {};
80	for (const k of (b10 ? ['n3','n10','pool'] : ['n3'])) {
81	  const i = D.idle[k], t = D['truncate-tail'][k], r = D.random[k];
82	  if (!i || !t || !r) continue;
83	  stats[k] = {
84	    n: i.n,
85	    vsTrunc: ft(i, t), vsRand: ft(i, r),
86	    vsPooled: i ? fisher(i.pass, i.n - i.pass, t.pass + r.pass, (t.n - t.pass) + (r.n - r.pass)) : NaN,
87	  };
88	}
89	
90	// ── inline SVG helpers ──────────────────────────────────────────────────────
91	const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
92	const PAL = { grid: '#e6e6ef', text: '#2b2b38', muted: '#7a7a8c' };
