1	/**
2	 * Context-eviction policies under test — PURE and importable so they can be unit
3	 * tested without executing a live sweep.
4	 *
5	 * DESIGN (v2, after adversarial review found five blockers in v1):
6	 *  - All capped policies fit the SAME budget W with the SAME anchor rule and
7	 *    differ ONLY in the ORDER they sacrifice units. That makes them
8	 *    volume-matched by construction, so a difference between arms is a
9	 *    difference in SELECTION SIGNAL, not in how much was evicted (review M2).
10	 *  - `idleOf` keys on FILE PATHS, not the `fp` fingerprint. `fp` admits any
11	 *    token with an underscore and length>=5, so `__init__` — shared by every
12	 *    Python module — linked every unit to the newest one and pinned idle near 0.
13	 *    Measured on this repo's own task: idleOf [1,1,6,1,4,3,1,1,0] vs truth
14	 *    [8,7,6,5,4,3,2,1,0]. That made the idle arm nearly inert (review BLOCKER 1).
15	 *  - The budget fit is IDLE-ORDERED for the idle arm rather than delegating to
16	 *    `evictRecency`, which keeps a contiguous suffix and therefore deleted
17	 *    exactly the positionally-old-but-re-referenced unit the idle rule had just
18	 *    saved, in every cell where the cap binds (review BLOCKER 2).
19	 *
20	 * INVARIANT every policy preserves: units come from `extractUnits`, so an
21	 * assistant message with tool_calls always travels with its tool results — a
22	 * tool result can never be orphaned from its call.
23	 */
24	import { extractUnits, estTokens } from '../coding-harness/lib.mjs';
25	
26	export const DEFAULT_ANCHOR = 4;
27	export const DEFAULT_RESERVE = 512;
28	
29	/** Deterministic PRNG (mulberry32) so the random control reruns identically. */
30	export function makeRng(seed = 0x9e3779b9) {
31	  let s = seed | 0;
32	  return () => {
33	    s = (s + 0x6d2b79f5) | 0;
34	    let t = Math.imul(s ^ (s >>> 15), 1 | s);
35	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
36	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
37	  };
38	}
39	
40	/** Replace `messages` with pinned head + kept units, in creation order, in place. */
41	export function rebuildLocal(messages, pinned, keptUnits) {
42	  const next = [...pinned, ...keptUnits.flatMap((u) => u.slice)];
43	  messages.length = 0;
44	  messages.push(...next);
45	}
46	
47	/** Indices of the recency anchor (the last `anchor` units) — never evicted. */
48	export function anchorSet(n, anchor = DEFAULT_ANCHOR) {
49	  return new Set(Array.from({ length: Math.min(Math.max(0, anchor), n) }, (_, k) => n - 1 - k));
50	}
51	
52	/**
53	 * Turns since each unit's FILE was last touched by a later unit (reference
54	 * recency). Units with no file identity (e.g. a `run_bash` test run) have no
55	 * path to re-reference, so they fall back to positional age.
56	 */
57	export function idleOf(units) {
58	  const N = units.length;
59	  return units.map((u, i) => {
60	    const files = u.files instanceof Set ? u.files : new Set();
61	    if (files.size === 0) return N - 1 - i;
62	    let last = i;
63	    for (let j = N - 1; j > i; j--) {
64	      let hit = false;
65	      for (const f of files) if (units[j].files.has(f)) { hit = true; break; }
66	      if (hit) { last = j; break; }
67	    }
68	    return N - 1 - last;
69	  });
70	}
71	
72	/**
73	 * Generic budget fit. `rank(units, anchorIdx, idle)` returns the NON-ANCHOR unit
74	 * indices in preferred-KEEP order (best first); we keep anchors, then take from
75	 * `rank` while the budget allows. Every arm shares this, so arms are
76	 * volume-matched and differ only in `rank`.
77	 *
78	 * Returns { changed, kept, evicted, capViolated } — `capViolated` is true when
79	 * the forced anchor alone exceeds W, so a floor override is VISIBLE rather than
80	 * silently breaking the cap (review M3).
81	 */
82	export function evictToBudget(messages, W, rank, opts = {}) {
83	  const anchor = opts.anchor ?? DEFAULT_ANCHOR;
84	  const reserve = opts.reserve ?? DEFAULT_RESERVE;
85	  const { pinned, units } = extractUnits(messages);
86	  const N = units.length;
87	  if (N === 0) return { changed: false, kept: 0, evicted: 0, capViolated: false };
88	
89	  const avail = W - estTokens(pinned) - reserve;
90	  const keepAnchor = anchorSet(N, anchor);
91	  const idle = idleOf(units);
92	  const keep = new Set(keepAnchor);
93	  let used = [...keepAnchor].reduce((s, i) => s + estTokens(units[i].slice), 0);
94	
95	  for (const i of rank(units, keepAnchor, idle)) {
96	    if (keep.has(i)) continue;
97	    const t = estTokens(units[i].slice);
98	    if (used + t <= avail) { keep.add(i); used += t; }
99	  }
100	
101	  const changed = keep.size !== N;
102	  if (changed) rebuildLocal(messages, pinned, [...keep].sort((a, b) => a - b).map((i) => units[i]));
103	  return { changed, kept: keep.size, evicted: N - keep.size, capViolated: estTokens(messages) > W };
104	}
105	
106	const nonAnchor = (units, anchorIdx) => units.map((_, i) => i).filter((i) => !anchorIdx.has(i));
107	
108	/** BASELINE (what real harnesses do): keep the most recent units that fit. */
109	export const rankRecency = (units, anchorIdx) => nonAnchor(units, anchorIdx).sort((a, b) => b - a);
110	
111	/** CONTROL: no selection signal — keep a random subset that fits. */
112	export const rankRandom = (rng = makeRng()) => (units, anchorIdx) => {
113	  const rest = nonAnchor(units, anchorIdx);
114	  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
115	  return rest;
116	};
117	
118	/**
119	 * TREATMENT: keep the units whose files were referenced most recently (lowest
120	 * idle) — reference recency rather than positional recency. Ties break toward
121	 * the newer unit so it is never worse than recency on a tie.
122	 */
123	export const rankIdle = (units, anchorIdx, idle) =>
124	  nonAnchor(units, anchorIdx).sort((a, b) => (idle[a] - idle[b]) || (b - a));
125	
126	/**
127	 * BLEND: interpolate between positional recency (alpha=0) and reference recency
128	 * (alpha=1). Ranks each unit by both and keeps the lowest weighted rank, so the
129	 * "strength of the LRU signal" becomes a continuous dial rather than on/off.
130	 */
131	export const rankBlend = (alpha) => (units, anchorIdx, idle) => {
132	  const rest = nonAnchor(units, anchorIdx);
133	  const posRank = new Map(); [...rest].sort((a, b) => b - a).forEach((i, r) => posRank.set(i, r));
134	  const idleRank = new Map(); [...rest].sort((a, b) => (idle[a] - idle[b]) || (b - a)).forEach((i, r) => idleRank.set(i, r));
135	  return rest.sort((a, b) =>
136	    (alpha * idleRank.get(a) + (1 - alpha) * posRank.get(a)) -
137	    (alpha * idleRank.get(b) + (1 - alpha) * posRank.get(b)));
138	};
139	
140	/** PROTECTION: units fresher than `g` are never evicted, even under budget pressure. */
141	export const rankProtect = (g) => (units, anchorIdx, idle) =>
142	  nonAnchor(units, anchorIdx).sort((a, b) => {
143	    const pa = idle[a] <= g ? 0 : 1, pb = idle[b] <= g ? 0 : 1;   // protected first
144	    return (pa - pb) || (idle[a] - idle[b]) || (b - a);
145	  });
146	
147	export const evictByBlend = (messages, W, alpha, opts) => evictToBudget(messages, W, rankBlend(alpha), opts);
148	export const evictByRecency = (messages, W, opts) => evictToBudget(messages, W, rankRecency, opts);
149	export const evictByRandom = (messages, W, rng, opts) => evictToBudget(messages, W, rankRandom(rng), opts);
150	export const evictByIdle = (messages, W, opts) => evictToBudget(messages, W, rankIdle, opts);

