66	  for (let k = 0; k < DISTRACTORS; k++) {
67	    const ds = SECTORS[(n + 1 + k) % SECTORS.length];
68	    if (ds === sector) continue;
69	    const dc = 1000 + Math.floor(rng() * 8999);
70	    const pos = Math.floor(((k + 1) / (DISTRACTORS + 1)) * lines.length);
71	    lines.splice(pos, 0, `IMPORTANT RECORD: the access code for sector ${ds} is ${dc}.`);
72	  }
73	  const at = Math.min(lines.length - 1, Math.max(0, Math.round(depth * (lines.length - 1))));
74	  lines.splice(at, 0, needle);
75	  const user = `${lines.join('\n')}\n\nQuestion: what is the access code for sector ${sector}? Answer with the 4-digit number only.`;
76	  const t0 = Date.now();
77	  let content = '', usage = null, err = null;
78	  try { const r = await generate({ system: SYSTEM, user, maxTokens: 32, temperature: 0, think: false }); content = r.content || ''; usage = r.usage || null; }
79	  catch (e) { err = String(e.message || e).slice(0, 120); }
80	  const hit = new RegExp(`(^|[^0-9])${code}([^0-9]|$)`).test(content);
81	  return { len, depth, needle_idx: n, sector, code, hit, answer: content.trim().slice(0, 40),
82	    prompt_tokens: usage?.prompt_tokens ?? null, depth_line: at, total_lines: lines.length,
83	    seconds: Math.round((Date.now() - t0) / 1000), error: err };
84	}
